// Matematik — Eşlik ve Benzerlik (M.8.3.3): Kademe 3 (LGS Ayarı) yedeği, sıra 26-75 (mat-eb-326 … mat-eb-375)
// 30 düzey 3 + 20 düzey 4. Karşılık gelen kenar/açı eşleştirme, benzerlik oranı, çevre, x'li kenar ifadeleri, kareli kâğıt, iki eşleştirme olasılığı, "kaç farklı / en az / en fazla". KKK/AKA kuralları, alan oranı ve gölge-Tales tipi problemler yoktur. Şekiller ölçeklidir.
window.LGS_BANK = window.LGS_BANK || {};
(window.LGS_BANK["eslik-benzerlik"] = window.LGS_BANK["eslik-benzerlik"] || []).push(
{
  id: "mat-eb-326",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir yayınevi, 16 cm × 24 cm boyutundaki dikdörtgen biçimli bir romanın cep boy baskısını hazırlıyor. Cep boy kapağın resmi bozulmadan küçültülecek; yani yeni kapak, eski kapağa benzer olacak. Tasarımcı, yeni kapak için dört ayrı boyut denemiştir.\n**Bu boyutlardan hangisi, eski kapağa benzer bir kapak verir?**",
  gorsel: null,
  secenekler: ["8 cm × 16 cm","10 cm × 15 cm","10 cm × 18 cm","12 cm × 20 cm"],
  dogru: 1,
  hatalar: ["Kısa kenarı uzun kenarına oranı [[1|2]] olan bir kapak seçtin; eski kapakta bu oran 16 / 24 = [[2|3]]'tür, oranlar eşit değil.",null,"Her kenardan 6 cm çıkardın (16 − 6 ve 24 − 6); benzerlikte kenarlardan aynı sayı çıkarılmaz, kenarlar aynı sayıyla çarpılır ya da bölünür.","Kısa / uzun oranı 12 / 20 = [[3|5]] çıkar; eski kapağın oranı [[2|3]]'tür, kenarlar orantılı değil."],
  aciklama: "Benzer dikdörtgenlerde açılar 90°'dir; benzer olmaları için kenarların aynı oranda olması gerekir. Bu yüzden kısa kenarın uzun kenara oranı iki dikdörtgende de aynı çıkmalıdır.\nAdım 1: Eski kapakta kısa / uzun = 16 / 24 = [[2|3]] bulunur.\nAdım 2: Seçenekleri sırayla dene: 8 / 16 = [[1|2]], 10 / 15 = [[2|3]], 10 / 18 = [[5|9]], 12 / 20 = [[3|5]].\nAdım 3: Yalnızca 10 × 15 aynı oranı verir; her kenar [[5|8]] katına inmiştir (16 · [[5|8]] = 10 ve 24 · [[5|8]] = 15).\nSık yapılan hata: Her kenardan aynı sayıyı çıkarmak (16 − 6 = 10 ve 24 − 6 = 18); benzerlikte kenarlar aynı sayıyla çarpılır, toplanıp çıkarılmaz.\nCevap B."
},
{
  id: "mat-eb-327",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir tasarımcı, ABC üçgeni biçimindeki bir logoyu büyüterek DEF logosunu elde ediyor (ABC ~ DEF). Büyütülen logo, şekilde ters çevrilmiş konumda çizilmiştir. Bazı kenar uzunlukları santimetre cinsinden verilmiştir.\n**x kaç santimetredir?**",
  gorsel: "<svg viewBox=\"4 22 393 155\" role=\"img\" aria-label=\"Benzer iki üçgen, ikincisi ters çevrilmiş\"><polygon points=\"30,120 78,120 96,50.3\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"17.1\" y=\"131\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"54\" y=\"139\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><text x=\"86.6\" y=\"136.6\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"108.7\" y=\"95.8\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><text x=\"102.8\" y=\"43.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"44.5\" y=\"72.7\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><polygon points=\"230,78.4 305.2,51.1 373.1,150\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"216\" y=\"83.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"309.4\" y=\"43.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"360.8\" y=\"90.7\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">15 cm</text><text x=\"383.7\" y=\"164.7\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"294.8\" y=\"132.6\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">x</text></svg>",
  secenekler: ["10","15","18","20"],
  dogru: 3,
  hatalar: ["|AB| = 6 cm kenarının karşılığını buldun (6 · [[5|3]] = 10); x ise F ve D köşelerini birleştirir, bunların karşılığı C ve A olduğundan |CA| kenarına karşılık gelir.","Şekilde verilen |EF| = 15 cm değerini cevap sandın; x başka bir kenardır.","Farkla çözdün: |EF| ile |BC| arasındaki fark 15 − 9 = 6 olduğundan 12 + 6 = 18 yazdın; benzerlikte fark eklenmez, oranla çarpılır.",null],
  aciklama: "Benzer çokgenlerde karşılık gelen köşeler yazılış sırasına göre eşleşir: ABC ~ DEF ise A ↔ D, B ↔ E, C ↔ F olur. Şekil döndürülmüş ya da ters çizilmiş olsa da eşleşme değişmez.\nAdım 1: x = |FD| kenarının uçları F ve D'dir; bunların karşılığı C ve A olduğundan |FD| kenarı |CA| = 12 cm kenarına karşılık gelir.\nAdım 2: Oranı bilinen bir kenar çiftinden bul: |EF| ile |BC| karşılıktır, oran 15 / 9 = [[5|3]].\nAdım 3: x = 12 · [[5|3]] = 20 cm olur.\nSağlama: En uzun kenar (12) en uzun kenara (20) karşılık geldi; |DE| = 6 · [[5|3]] = 10 cm de en kısa kenar olur.\nCevap D."
},
{
  id: "mat-eb-328",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir oyuncak firması, gerçek bir otomobilin görünümünü bozmadan küçülterek modelini üretiyor; model ile otomobil benzerdir. Gerçek otomobilin uzunluğu 4,5 m, yüksekliği 1,5 m; modelin uzunluğu ise 30 cm'dir. Boyutlar tabloda verilmiştir.\n**Modelin yüksekliği kaç santimetredir?**",
  gorsel: "<table class=\"tablo\"><tr><th></th><th>Uzunluk</th><th>Yükseklik</th></tr><tr><td>Gerçek otomobil</td><td>4,5 m</td><td>1,5 m</td></tr><tr><td>Model</td><td>30 cm</td><td>?</td></tr></table>",
  secenekler: ["10","27","45","90"],
  dogru: 0,
  hatalar: [null,"Uzunluklar arasındaki farkı (4,5 − 1,5 = 3) modelin uzunluğundan çıkardın (30 − 3); benzerlikte fark değil oran korunur.","Modelin uzunluğunu 1,5 ile çarptın; yüksekliğe ulaşmak için uzunluk / yükseklik oranı olan 3'e bölmek gerekir.","Oranı ters kullanıp 30 · 3 yaptın; yükseklik uzunluktan küçüktür, bu yüzden bölünür."],
  aciklama: "Benzer şekillerde karşılık gelen uzunluklar aynı oranda büyür ya da küçülür. Bu yüzden bir şeklin uzunluk / yükseklik oranı, benzeri olan şekilde de aynı kalır.\nAdım 1: Gerçek otomobilde uzunluk / yükseklik = 4,5 / 1,5 = 3'tür; yani yükseklik uzunluğun [[1|3]]'idir.\nAdım 2: Model otomobile benzer olduğundan modelin yüksekliği de uzunluğunun [[1|3]]'idir: 30 ÷ 3 = 10 cm.\nSağlama: Benzerlik oranı 30 / 450 = [[1|15]] (4,5 m = 450 cm); gerçek yükseklik 150 cm olduğundan 150 · [[1|15]] = 10 cm bulunur.\nSık yapılan hata: Uzunluk ile yüksekliğin oranını ters kurmak ya da iki uzunluğun farkını kullanmak.\nCevap A."
},
{
  id: "mat-eb-329",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir mobilya atölyesi, paralelkenar biçimli iki sehpa tablası tasarlamıştır. ABCD tablasında |AB| = 6 cm, |BC| = 9 cm ve m(A) = 70°; EFGH tablasında |EF| = 8 cm, |FG| = 12 cm ve m(E) = 80°'dir (ölçüler maket ölçüleridir).\n**Bu iki tabla için aşağıdakilerden hangisi doğrudur?**",
  gorsel: "<svg viewBox=\"5 -1 341 152\" role=\"img\" aria-label=\"Paralelkenar biçimli iki tabla\"><polygon points=\"30,100 78,100 102.6,32.3 54.6,32.3\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"18.5\" y=\"113.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"54\" y=\"119\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><text x=\"57.9\" y=\"85.5\" font-size=\"13\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">70°</text><text x=\"86\" y=\"117\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"111.7\" y=\"79\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><text x=\"114.1\" y=\"29.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"46.6\" y=\"26.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><polygon points=\"220,120 284,120 300.7,25.5 236.7,25.5\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"209.3\" y=\"134.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"252\" y=\"139\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"246\" y=\"103.1\" font-size=\"13\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">80°</text><text x=\"293\" y=\"136.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"317.8\" y=\"82.2\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"311.4\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">G</text><text x=\"227.7\" y=\"20.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">H</text></svg>",
  secenekler: ["Karşılık gelen kenarlar orantılı olduğundan tablalar benzerdir.","Karşılık gelen açılar farklı olduğundan tablalar eştir.","Karşılık gelen açılar eşit olmadığından tablalar benzer değildir.","Karşılık gelen kenarlar farklı olduğundan tablalar benzer değildir."],
  dogru: 2,
  hatalar: ["Kenarların orantılı olması tek başına yetmez; benzer olmak için karşılık gelen açılar da eşit olmalıdır (70° ≠ 80°).","Açıları farklı olan şekiller eş olamaz; eşlikte karşılık gelen bütün açılar ve kenarlar eşittir.",null,"Benzer şekillerin kenarları eşit değil orantılıdır; kenarların farklı olması benzerliği bozmaz. Asıl sorun, karşılık gelen açıların eşit olmamasıdır."],
  aciklama: "Benzerlik için iki koşul birlikte aranır: karşılık gelen açılar eşit olmalı ve karşılık gelen kenarlar orantılı olmalıdır. Yalnızca birinin sağlanması yetmez.\nAdım 1: Kenarları karşılaştır: |EF| / |AB| = 8 / 6 = [[4|3]] ve |FG| / |BC| = 12 / 9 = [[4|3]]. Kenarlar orantılıdır.\nAdım 2: Açıları karşılaştır: ABCD'de A açısı 70°, EFGH'de karşılığı olan E açısı 80°'dir. Karşılık gelen açılar eşit değildir.\nAdım 3: Açılar eşit olmadığından iki tabla benzer değildir (eş de değildir).\nSık yapılan hata: Kenarlar orantılı diye şekilleri benzer saymak; paralelkenarın açıları değişebilir.\nCevap C."
},
{
  id: "mat-eb-330",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Kareli kâğıda dik üçgen biçimli K, L, M, N ve P şekilleri çizilmiştir. Karelerin kenarı hepsinde 1 birimdir. Zeynep, K üçgeninin her kenarını aynı sayıyla çarparak büyütmek ve K'ye benzer, benzerlik oranı 2 olan bir üçgen elde etmek istiyor.\n**Bu üçgen aşağıdakilerden hangisidir?**",
  gorsel: "<svg viewBox=\"-8 -8 380 98\" role=\"img\" aria-label=\"Kareli kâğıtta beş dik üçgen\"><polygon points=\"0,56 42,56 0,28\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"56,56 126,56 56,0\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"140,56 224,56 140,14\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"238,56 322,56 238,0\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"336,56 364,56 364,14\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"14\" y1=\"0\" x2=\"14\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"28\" y1=\"0\" x2=\"28\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"42\" y1=\"0\" x2=\"42\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"56\" y1=\"0\" x2=\"56\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"70\" y1=\"0\" x2=\"70\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"84\" y1=\"0\" x2=\"84\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"98\" y1=\"0\" x2=\"98\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"112\" y1=\"0\" x2=\"112\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"126\" y1=\"0\" x2=\"126\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"140\" y1=\"0\" x2=\"140\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"154\" y1=\"0\" x2=\"154\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"168\" y1=\"0\" x2=\"168\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"182\" y1=\"0\" x2=\"182\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"196\" y1=\"0\" x2=\"196\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"210\" y1=\"0\" x2=\"210\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"224\" y1=\"0\" x2=\"224\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"238\" y1=\"0\" x2=\"238\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"252\" y1=\"0\" x2=\"252\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"266\" y1=\"0\" x2=\"266\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"280\" y1=\"0\" x2=\"280\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"294\" y1=\"0\" x2=\"294\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"308\" y1=\"0\" x2=\"308\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"322\" y1=\"0\" x2=\"322\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"336\" y1=\"0\" x2=\"336\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"350\" y1=\"0\" x2=\"350\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"364\" y1=\"0\" x2=\"364\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"364\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"14\" x2=\"364\" y2=\"14\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"28\" x2=\"364\" y2=\"28\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"42\" x2=\"364\" y2=\"42\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"56\" x2=\"364\" y2=\"56\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"21\" y=\"78\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"91\" y=\"78\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"182\" y=\"78\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"280\" y=\"78\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">N</text><text x=\"350\" y=\"78\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">P</text></svg>",
  secenekler: ["L şekli","M şekli","N şekli","P şekli"],
  dogru: 2,
  hatalar: ["Dik kenarlara 2 birim ekledin (3 + 2 ve 2 + 2); benzerlikte kenarlara sayı eklenmez, kenarlar aynı sayıyla çarpılır.","Yatay kenarı 2 katına çıkardın (3 → 6), ama düşey kenar 2'den 3'e, yani yalnızca 1,5 katına çıkmış; iki kenar da aynı oranda büyümelidir.",null,"P'nin dik kenarları 2 ve 3 birimdir; K ile aynı ölçülerdir, yalnızca yer değiştirmiştir. Bu eşliktir (oran 1), oran 2 değildir."],
  aciklama: "Benzerlik oranı 2 ise yeni şeklin her kenarı, K'nin karşılık gelen kenarının 2 katıdır; kenarlara sayı eklenmez, kenarlar çarpılır.\nAdım 1: Kareli kâğıttan sayarak K üçgeninin dik kenarları 3 ve 2 birimdir.\nAdım 2: Oranı 2 olan üçgenin dik kenarları 3 · 2 = 6 ve 2 · 2 = 4 birim olmalıdır.\nAdım 3: Üçgenleri say: L 5 ve 4, M 6 ve 3, N 6 ve 4, P 2 ve 3 birimdir. Yalnızca N uygundur.\nSık yapılan hata: Her kenara aynı sayıyı eklemek (L üçgeninde olduğu gibi).\nCevap C."
},
{
  id: "mat-eb-331",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir peyzaj firması, aynı kalıptan iki dörtgen biçimli yapay çim levhası kesiyor (ABCD ≅ KLMN). ABCD levhasının kenar uzunlukları ve KLMN levhasının bir kenar uzunluğu santimetre cinsinden şekilde verilmiştir. Firma, KLMN levhasının kenarına şerit çıta çakacaktır.\n**Çıtanın uzunluğu KLMN levhasının çevresine eşit olduğuna göre kaç santimetredir?**",
  gorsel: "<svg viewBox=\"-6 -7 408 148\" role=\"img\" aria-label=\"Eş iki dörtgen biçimli çim levhası\"><polygon points=\"40,110 131,110 98.5,40.2 39,61\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"30.2\" y=\"125.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"85.5\" y=\"129\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">(3x − 2) cm</text><text x=\"142.8\" y=\"123\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"154.9\" y=\"61.4\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">(x + 6) cm</text><text x=\"103.9\" y=\"32.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"62.6\" y=\"38\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><text x=\"27.5\" y=\"58.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"18.6\" y=\"90.9\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">7 cm</text><polygon points=\"375.5,51.1 290,20 296.7,96.7 359.7,97.5\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"388.1\" y=\"50.6\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"339.7\" y=\"21.6\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">13 cm</text><text x=\"281.5\" y=\"14.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"287.2\" y=\"112.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"367.8\" y=\"114.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">N</text></svg>",
  secenekler: ["40","34","33","24"],
  dogru: 0,
  hatalar: [null,"|BC| yerine x = 5 değerini aldın; |BC| = x + 6 = 11 cm'dir.","|DA| = 7 cm kenarını katmadın; dörtgenin çevresi dört kenarın da toplamıdır.","Yalnızca iki kenarın toplamını (13 + 11) buldun; çevre dört kenarın toplamıdır."],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşittir; bu yüzden eş iki çokgenin çevreleri de eşittir.\nAdım 1: ABCD ≅ KLMN olduğundan A ↔ K, B ↔ L olur ve |AB| = |KL| yazılır: 3x − 2 = 13.\nAdım 2: 3x = 15 ve x = 5 bulunur. Buna göre |BC| = x + 6 = 11 cm olur.\nAdım 3: KLMN'nin çevresi ABCD'nin çevresine eşittir: 13 + 11 + 9 + 7 = 40 cm.\nSağlama: |AB| = 3 · 5 − 2 = 13 cm, verilen |KL| = 13 cm ile uyuşur.\nCevap A."
},
{
  id: "mat-eb-332",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir okul gösterisinde sahnenin iki yanına dikdörtgen biçimli iki resim panosu konacaktır. Büyük pano, küçük panonun bozulmadan büyütülmüş hâlidir. Panoların ölçüleri santimetre cinsinden şekilde verilmiştir.\n**x kaçtır?**",
  gorsel: "<svg viewBox=\"37 -14 491 154\" role=\"img\" aria-label=\"Benzer iki dikdörtgen pano\"><polygon points=\"90,60 210,60 210,132 90,132\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"150\" y=\"51\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">20 cm</text><text x=\"65.4\" y=\"101\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><polygon points=\"340,14 520,14 520,122 340,122\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"430\" y=\"5\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">30 cm</text><text x=\"291.6\" y=\"73\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">(x + 3) cm</text></svg>",
  secenekler: ["27","19","18","15"],
  dogru: 3,
  hatalar: ["Kısa kenarı uzun kenarla eşleştirdin (x + 3 = 30, x = 27); x + 3 kenarı küçük panonun 12 cm kenarına karşılık gelir.","Farkla çözdün: uzun kenar 10 cm artmış diye kısa kenara da 10 ekledin (12 + 10 = 22, x = 19); benzerlikte kenarlar toplanmaz, orantılanır.","x + 3 = 18 buldun ama 3'ü çıkarmadın; kenarın uzunluğu x değil x + 3'tür.",null],
  aciklama: "Benzer dikdörtgenlerde karşılık gelen kenarların oranı sabittir. Büyük dikdörtgenin uzun kenarı küçüğün uzun kenarına, kısa kenarı kısa kenarına karşılık gelir.\nAdım 1: Uzun kenarlardan oranı bul: 30 / 20 = [[3|2]].\nAdım 2: Kısa kenarlar da aynı oranla büyür: x + 3 = 12 · [[3|2]] = 18.\nAdım 3: x = 18 − 3 = 15 bulunur.\nSağlama: x + 3 = 18 ve 18 / 12 = [[3|2]] = 30 / 20; kenarlar orantılı.\nSık yapılan hata: x + 3 ifadesini kenarın kendisi sanıp 18'i cevap yazmak.\nCevap D."
},
{
  id: "mat-eb-333",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bahçıvan Şener Usta, üçgen biçimli iki çiçeklik hazırlıyor. ABC çiçekliği küçük, DEF çiçekliği büyük olandır ve ABC ~ DEF'dir. Küçük çiçekliğin kenarları ile büyük çiçekliğin bir kenarı metre cinsinden şekilde verilmiştir. Usta, büyük çiçekliğin çevresine tek sıra çit çekecektir.\n**Çitin uzunluğu kaç metredir?**",
  gorsel: "<svg viewBox=\"4 30 401 131\" role=\"img\" aria-label=\"Benzer iki üçgen çiçeklik\"><polygon points=\"30,100 142,100 68.5,59.3\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"17.1\" y=\"111\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"86\" y=\"119\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 m</text><text x=\"155.6\" y=\"109\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"114.2\" y=\"68.4\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 m</text><text x=\"66.4\" y=\"51\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"34.9\" y=\"71.1\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">4 m</text><polygon points=\"210,130 378,130 267.8,69\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"197.1\" y=\"141\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"294\" y=\"149\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 m</text><text x=\"391.6\" y=\"139\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"265.6\" y=\"60.7\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text></svg>",
  secenekler: ["27","30","36","54"],
  dogru: 0,
  hatalar: [null,"Her kenara 4 m ekledin (8 → 12 olduğu için 4 + 4, 6 + 4, 8 + 4); benzerlikte kenarlara sayı eklenmez, aynı oranla çarpılır.","En uzun kenarı küçük çiçekliğin orta kenarıyla oranlayıp (12 / 6 = 2) 18 · 2 yaptın; karşılık gelen kenarlar en uzun ile en uzundur.","En uzun kenarı küçük çiçekliğin en kısa kenarıyla oranladın (12 / 4 = 3) ve 18 · 3 yaptın; karşılık gelen kenarlar en uzun ile en uzundur."],
  aciklama: "Benzer çokgenlerde çevreler de kenarlarla aynı oranda değişir: çevreler oranı = benzerlik oranı.\nAdım 1: ABC ~ DEF olduğundan A ↔ D, B ↔ E olur; en uzun kenarlar karşılık gelir: |AB| = 8 m ile |DE| = 12 m. Benzerlik oranı 12 / 8 = [[3|2]].\nAdım 2: ABC'nin çevresi 8 + 6 + 4 = 18 m'dir.\nAdım 3: DEF'nin çevresi 18 · [[3|2]] = 27 m olur.\nSağlama: Diğer kenarlar 6 · [[3|2]] = 9 m ve 4 · [[3|2]] = 6 m olur; 12 + 9 + 6 = 27.\nCevap A."
},
{
  id: "mat-eb-334",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir çadır firması, ön yüzü ikizkenar üçgen biçimli ABC çadırının büyütülmüş modelini (DEF) üretiyor. ABC üçgeninde |AB| = |AC| ve m(A) = 40°'dir. ABC ~ DEF'dir ve DEF çadırının çizimi şekilde ters çevrilmiş olarak gösterilmiştir. DEF üçgeninde E köşesindeki açının ölçüsü (2x + 10)°'dir.\n**x kaçtır?**",
  gorsel: "<svg viewBox=\"24 -9 347 187\" role=\"img\" aria-label=\"İkizkenar üçgen ve ters çizilmiş benzeri\"><polygon points=\"80,20 49.2,104.6 110.8,104.6\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"80\" y=\"11.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"80\" y=\"77\" font-size=\"13\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">40°</text><text x=\"37.8\" y=\"118.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"122.2\" y=\"118.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><polygon points=\"300,146.9 253.8,20 346.2,20\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"300\" y=\"166.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"242.4\" y=\"17.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"357.6\" y=\"17.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"239.8\" y=\"48\" font-size=\"13\" text-anchor=\"end\" fill=\"var(--vurgu)\" font-weight=\"700\">(2x + 10)°</text></svg>",
  secenekler: ["15","30","50","65"],
  dogru: 1,
  hatalar: ["E açısını A açısıyla eşleştirdin (2x + 10 = 40); E köşesi B'nin karşılığıdır, A'nın değil.",null,"E açısını 110° aldın (2x + 10 = 110); bu üçgenin açıları 40°, 70° ve 70°'dir, 110° yoktur.","E açısını 140° aldın (180° − 40°); bu değer iki taban açısının toplamıdır, tek bir açının ölçüsü değil."],
  aciklama: "İkizkenar üçgende eşit kenarların karşısındaki açılar (taban açıları) eşittir. Benzer üçgenlerde karşılık gelen açılar da eşittir.\nAdım 1: ABC'de |AB| = |AC| ve m(A) = 40° olduğundan m(B) = m(C) = (180° − 40°) ÷ 2 = 70°.\nAdım 2: ABC ~ DEF olduğundan B ↔ E eşleşir; m(E) = m(B) = 70° olur. DEF ters çizilmiş olsa da eşleşme harf sırasına göredir.\nAdım 3: 2x + 10 = 70 denkleminden 2x = 60 ve x = 30 bulunur.\nSağlama: 2 · 30 + 10 = 70.\nCevap B."
},
{
  id: "mat-eb-335",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Hazal, 24 cm × 36 cm boyutlarındaki dikdörtgen biçimli bir ders notunu fotokopi makinesinde art arda iki kez kopyalıyor. Makine önce kâğıdı [[5|4]] oranında büyütüyor, çıkan kopyayı ise [[2|3]] oranında küçültüyor. Her iki işlemde de iki kenar aynı oranda değişiyor.\n**Son kopyanın kenar uzunlukları aşağıdakilerden hangisidir?**",
  gorsel: null,
  secenekler: ["46 cm × 69 cm","30 cm × 45 cm","20 cm × 30 cm","16 cm × 24 cm"],
  dogru: 2,
  hatalar: ["Oranları çarpmak yerine topladın ([[5|4]] + [[2|3]] = [[23|12]]); art arda gelen oranlar çarpılır.","Yalnızca büyütmeyi uyguladın (24 · [[5|4]] = 30); ikinci adımdaki küçültmeyi unuttun.",null,"Yalnızca küçültme oranını uyguladın (24 · [[2|3]] = 16); büyütme adımını atladın."],
  aciklama: "Kâğıdın her kenarı aynı oranla büyütülüp küçültüldüğünde şekil benzer kalır. Art arda gelen iki oran çarpılır: toplam oran = [[5|4]] · [[2|3]].\nAdım 1: Toplam oran = [[5|4]] · [[2|3]] = [[10|12]] = [[5|6]].\nAdım 2: Kısa kenar 24 · [[5|6]] = 20 cm olur.\nAdım 3: Uzun kenar 36 · [[5|6]] = 30 cm olur.\nSağlama: Adım adım git: 24 → 30 → 20 ve 36 → 45 → 30; aynı sonuç çıkar.\nSık yapılan hata: Oranları toplamak ([[5|4]] + [[2|3]]).\nCevap C."
},
{
  id: "mat-eb-336",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir çıkartma tasarımcısı, haç biçimli bir çıkartmanın (R) farklı boylarını kareli kâğıda çizmiştir. Karelerin kenarı hepsinde 1 birimdir ve bütün açılar diktir.\n**Bu şekillerden hangisi R şekline benzerdir?**",
  gorsel: "<svg viewBox=\"-8 -8 376 138\" role=\"img\" aria-label=\"Kareli kâğıtta haç biçimli beş şekil\"><polygon points=\"12,60 24,60 24,72 36,72 36,84 24,84 24,96 12,96 12,84 0,84 0,72 12,72\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"72,36 84,36 84,60 108,60 108,72 84,72 84,96 72,96 72,72 48,72 48,60 72,60\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"132,48 156,48 156,60 168,60 168,84 156,84 156,96 132,96 132,84 120,84 120,60 132,60\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"204,24 228,24 228,48 252,48 252,72 228,72 228,96 204,96 204,72 180,72 180,48 204,48\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"300,0 324,0 324,36 360,36 360,60 324,60 324,96 300,96 300,60 264,60 264,36 300,36\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"12\" y1=\"0\" x2=\"12\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"24\" y1=\"0\" x2=\"24\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"36\" y1=\"0\" x2=\"36\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"48\" y1=\"0\" x2=\"48\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"60\" y1=\"0\" x2=\"60\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"72\" y1=\"0\" x2=\"72\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"84\" y1=\"0\" x2=\"84\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"96\" y1=\"0\" x2=\"96\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"108\" y1=\"0\" x2=\"108\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"120\" y1=\"0\" x2=\"120\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"132\" y1=\"0\" x2=\"132\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"144\" y1=\"0\" x2=\"144\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"156\" y1=\"0\" x2=\"156\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"168\" y1=\"0\" x2=\"168\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"180\" y1=\"0\" x2=\"180\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"192\" y1=\"0\" x2=\"192\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"204\" y1=\"0\" x2=\"204\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"216\" y1=\"0\" x2=\"216\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"228\" y1=\"0\" x2=\"228\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"240\" y1=\"0\" x2=\"240\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"252\" y1=\"0\" x2=\"252\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"264\" y1=\"0\" x2=\"264\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"276\" y1=\"0\" x2=\"276\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"288\" y1=\"0\" x2=\"288\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"300\" y1=\"0\" x2=\"300\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"312\" y1=\"0\" x2=\"312\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"324\" y1=\"0\" x2=\"324\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"336\" y1=\"0\" x2=\"336\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"348\" y1=\"0\" x2=\"348\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"360\" y1=\"0\" x2=\"360\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"360\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"12\" x2=\"360\" y2=\"12\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"24\" x2=\"360\" y2=\"24\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"36\" x2=\"360\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"48\" x2=\"360\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"60\" x2=\"360\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"72\" x2=\"360\" y2=\"72\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"84\" x2=\"360\" y2=\"84\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"96\" x2=\"360\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"18\" y=\"118\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><text x=\"78\" y=\"118\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"144\" y=\"118\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"216\" y=\"118\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"312\" y=\"118\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">N</text></svg>",
  secenekler: ["K şekli","L şekli","M şekli","N şekli"],
  dogru: 2,
  hatalar: ["Kollar 2 katına uzamış ama kalınlık 1'de kalmış; kenarlar aynı oranda büyümediği için K benzer değildir.","Kalınlık 2 katına çıkmış ama kolların uzunluğu 1'de kalmış; kenarlar orantılı değildir.",null,"Kol uzunluğu 3 katına, kalınlık 2 katına çıkmış; ölçüler farklı oranlarda büyüdüğü için N benzer değildir."],
  aciklama: "Benzer şekillerde karşılık gelen bütün kenarlar aynı oranda büyür. Haç biçiminde üç ölçüye bakılır: kolların uzunluğu, kolların kalınlığı ve toplam genişlik.\nAdım 1: R haçında kollar 1 birim uzunlukta ve 1 birim kalınlıktadır; toplam genişlik 3 birimdir.\nAdım 2: Aday haçlarda (kol uzunluğu / kalınlık / genişlik) şöyledir: K 2 / 1 / 5, L 1 / 2 / 4, M 2 / 2 / 6, N 3 / 2 / 8.\nAdım 3: R'nin ölçüleri 1 / 1 / 3'tür; hepsi aynı sayıyla çarpılmalıdır. M'de 1 · 2, 1 · 2, 3 · 2 olduğundan M, R'nin 2 katıdır; diğerlerinde ölçüler farklı oranlarda değişmiştir.\nSık yapılan hata: Yalnızca dış genişliğe bakmak; kol kalınlığı da aynı oranda büyümelidir.\nCevap C."
},
{
  id: "mat-eb-337",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir oyuncak yapımcısı, B köşesi dik açı olan ABC dik üçgeni biçimindeki bir rampanın küçültülmüş modelini (DEF) yapıyor ve ABC ~ DEF'dir. E köşesi de dik açıdır. Bazı kenar uzunlukları santimetre cinsinden şekilde verilmiştir.\n**Modelin eğik kenarı olan |DF| = x kaç santimetredir?**",
  gorsel: "<svg viewBox=\"-5 -9 350 140\" role=\"img\" aria-label=\"Benzer iki dik üçgen\"><polygon points=\"40,19 40,100 148,100\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"33.7\" y=\"12\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"19.3\" y=\"64.5\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><text x=\"30.1\" y=\"115.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"94\" y=\"119\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"161.3\" y=\"109.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><polygon points=\"40,100 40,90 50,90 50,100\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><polygon points=\"300,46 300,100 228,100\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"306.3\" y=\"39\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"320.7\" y=\"78\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><text x=\"309.9\" y=\"115.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"214.7\" y=\"109.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"255.1\" y=\"66.2\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">x</text><polygon points=\"300,100 300,90 290,90 290,100\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>",
  secenekler: ["8","10","12","15"],
  dogru: 1,
  hatalar: ["|EF| dik kenarını buldun (12 · [[2|3]] = 8); x ise dik açının karşısındaki en uzun kenar olan |DF|'dir.",null,"Fark kullandın: |AB| ile |DE| arasındaki fark 3 olduğundan 15 − 3 = 12 yazdın; kenarlar oranla çarpılır, fark çıkarılmaz.","Küçültmeden |AC| = 15 cm değerini cevap yazdın; DEF küçültülmüş olduğundan |DF| 15'ten küçüktür."],
  aciklama: "Dik üçgende dik kenarların kareleri toplamı hipotenüsün (dik açının karşısındaki kenarın) karesine eşittir: a^{2} + b^{2} = c^{2}. Benzer üçgenlerde karşılık gelen kenarlar aynı oranda olduğundan hipotenüs de aynı oranla değişir.\nAdım 1: ABC dik üçgeninde |AC|^{2} = 9^{2} + 12^{2} = 81 + 144 = 225 olduğundan |AC| = 15 cm.\nAdım 2: ABC ~ DEF olduğundan |DE| ↔ |AB|; oran 6 / 9 = [[2|3]].\nAdım 3: x = |DF| = |AC| · [[2|3]] = 15 · [[2|3]] = 10 cm.\nSağlama: |EF| = 12 · [[2|3]] = 8 cm; 6^{2} + 8^{2} = 36 + 64 = 100 = 10^{2}.\nCevap B."
},
{
  id: "mat-eb-338",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir yapboz tasarımcısı, basamaklı R parçasının kalıbını kareli kâğıda çizmiş; ardından R'nin yanına dört parça daha çizmiştir. Karelerin kenarı hepsinde 1 birimdir.\n**Aşağıdaki şekillerden hangisi R şekline eştir?**",
  gorsel: "<svg viewBox=\"-8 -8 316 78\" role=\"img\" aria-label=\"Kareli kâğıtta basamaklı beş şekil\"><polygon points=\"0,12 36,12 36,24 24,24 24,36 0,36\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"60,12 108,12 108,24 84,24 84,36 60,36\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"132,12 168,12 168,24 144,24 144,36 132,36\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"216,0 216,36 204,36 204,24 192,24 192,0\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"240,0 276,0 276,12 264,12 264,36 240,36\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"12\" y1=\"0\" x2=\"12\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"24\" y1=\"0\" x2=\"24\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"36\" y1=\"0\" x2=\"36\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"48\" y1=\"0\" x2=\"48\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"60\" y1=\"0\" x2=\"60\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"72\" y1=\"0\" x2=\"72\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"84\" y1=\"0\" x2=\"84\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"96\" y1=\"0\" x2=\"96\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"108\" y1=\"0\" x2=\"108\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"120\" y1=\"0\" x2=\"120\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"132\" y1=\"0\" x2=\"132\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"144\" y1=\"0\" x2=\"144\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"156\" y1=\"0\" x2=\"156\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"168\" y1=\"0\" x2=\"168\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"180\" y1=\"0\" x2=\"180\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"192\" y1=\"0\" x2=\"192\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"204\" y1=\"0\" x2=\"204\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"216\" y1=\"0\" x2=\"216\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"228\" y1=\"0\" x2=\"228\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"240\" y1=\"0\" x2=\"240\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"252\" y1=\"0\" x2=\"252\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"264\" y1=\"0\" x2=\"264\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"276\" y1=\"0\" x2=\"276\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"288\" y1=\"0\" x2=\"288\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"300\" y1=\"0\" x2=\"300\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"300\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"12\" x2=\"300\" y2=\"12\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"24\" x2=\"300\" y2=\"24\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"36\" x2=\"300\" y2=\"36\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"18\" y=\"58\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><text x=\"84\" y=\"58\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"150\" y=\"58\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"204\" y=\"58\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"258\" y=\"58\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">N</text></svg>",
  secenekler: ["K şekli","L şekli","M şekli","N şekli"],
  dogru: 2,
  hatalar: ["K'nin üst sırası 4 birimdir, R'ninki 3 birimdir; karşılık gelen kenarlar eşit olmadığı için eş değildir.","L'de alt basamak 1 birimdir, R'de 2 birimdir; kenarlar uyuşmadığı için eş değildir.",null,"N, R'den bir birim daha yüksektir; kenarlar eşit olmadığı için eş değildir."],
  aciklama: "Eş şekiller, üst üste konunca tam örtüşür; yani karşılık gelen bütün kenarlar ve açılar eşittir. Yönü farklı çizilmiş olsa da tam örtüşen şekil eştir.\nAdım 1: R şekli, üst sırada 3 kare ve alt sırada 2 kare olan, toplam 5 kareden oluşan basamaklıdır.\nAdım 2: K'de üst sıra 4, L'de alt sıra 1, N'de ek bir sıra var; üçünün kare sayısı ya da kenarları R'den farklıdır.\nAdım 3: M şekli de 5 kareden oluşur; R ile aynı parçadır ama yan yatık çizilmiştir. Dikey 3, yatay 2 birim ölçüleri ve basamaklar R ile aynıdır.\nSık yapılan hata: Biçimi benzer görünen ama bir kenarı farklı olan şekli eş saymak.\nCevap C."
},
{
  id: "mat-eb-339",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir elektronik mağazası, dikdörtgen biçimli iki tablet ekranını tanıtıyor. Ekranlar benzerdir. Küçük ekranın kenarları 16 cm ve 12 cm, büyük ekranın köşegeni ise 50 cm'dir.\n**Büyük ekranın çevresi kaç santimetredir?**",
  gorsel: "<svg viewBox=\"7 22 381 136\" role=\"img\" aria-label=\"Benzer iki ekran\"><polygon points=\"60,90 124,90 124,138 60,138\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"92\" y=\"81\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">16 cm</text><text x=\"35.4\" y=\"119\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><polygon points=\"220,30 380,30 380,150 220,150\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"220\" y1=\"150\" x2=\"380\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><text x=\"292\" y=\"78\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">50 cm</text></svg>",
  secenekler: ["140","120","112","70"],
  dogru: 0,
  hatalar: [null,"Köşegeni de çevreye kattın (40 + 30 + 50); köşegen dış kenar değildir, çevreye girmez.","Küçük ekranın çevresini 2 katına çıkardın; benzerlik oranı 2 değil, [[5|2]]'dir.","Yalnızca iki kenarın toplamını buldun (40 + 30); çevre dört kenarın toplamıdır."],
  aciklama: "Benzer dikdörtgenlerde köşegenler de kenarlarla aynı oranda değişir. Dik üçgen oluşturan kenarlarla köşegen arasında Pisagor bağıntısı vardır.\nAdım 1: Küçük ekranın köşegeni: 16^{2} + 12^{2} = 256 + 144 = 400 olduğundan 20 cm.\nAdım 2: Benzerlik oranı = 50 / 20 = [[5|2]].\nAdım 3: Büyük ekranın kenarları 16 · [[5|2]] = 40 cm ve 12 · [[5|2]] = 30 cm; çevre 2 · (40 + 30) = 140 cm.\nSağlama: 30^{2} + 40^{2} = 900 + 1600 = 2500 = 50^{2}.\nCevap A."
},
{
  id: "mat-eb-340",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Elif, benzerlik konusunu çalışırken bazı şekil çiftlerini karşılaştırıyor.\n**Aşağıdaki şekil çiftlerinden hangisi için \"bu iki şekil benzerdir\" demek her zaman doğrudur?**",
  gorsel: null,
  secenekler: ["Kenar sayıları aynı olan iki çokgen","Bir kenarı 5 cm olan iki ikizkenar üçgen","Çevreleri eşit olan iki dikdörtgen","Kenar uzunlukları farklı olan iki düzgün beşgen"],
  dogru: 3,
  hatalar: ["Kenar sayısı aynı olan çokgenlerin açıları ve kenar oranları farklı olabilir (ör. bir kare ile bir yamuk).","Bir kenarın eşit olması yetmez; açılar ve diğer kenarlar farklı olabilir.","Çevresi 20 cm olan 2 × 8 ve 5 × 5 dikdörtgenleri benzer değildir; çevrenin eşit olması benzerlik sağlamaz.",null],
  aciklama: "Benzer olmak için karşılık gelen açılar eşit ve karşılık gelen kenarlar orantılı olmalıdır. Düzgün çokgenin bütün kenarları eşit, bütün açıları eşittir.\nAdım 1: Düzgün bir beşgenin her açısı 108°'dir; iki düzgün beşgenin açıları her zaman eşittir.\nAdım 2: Her düzgün beşgende bütün kenarlar eşit olduğundan, kenar uzunlukları a ve b olan iki beşgende karşılık gelen kenar oranı her yerde [[a|b]]'dir; yani kenarlar orantılıdır.\nAdım 3: Diğer şıklarda ya açılar ya kenar oranları değişebilir; bu yüzden her zaman benzer denemez.\nSık yapılan hata: Tek bir ölçünün (kenar sayısı, bir kenar, çevre) eşit olmasını benzerlik için yeterli saymak.\nCevap D."
},
{
  id: "mat-eb-341",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir okul rozeti ABC üçgeni biçimindedir ve ABC ~ DEF olacak biçimde büyütülerek DEF rozeti yapılıyor. ABC üçgeninde m(A) = 80°, m(B) = (3x − 5)° ve m(C) = (2x − 10)°'dir. Büyük rozet şekilde döndürülmüş olarak çizilmiştir.\n**DEF üçgeninde m(F) kaç derecedir?**",
  gorsel: "<svg viewBox=\"16 -65 372 366\" role=\"img\" aria-label=\"Benzer iki üçgen\"><polygon points=\"40,130 150,130 69.2,-35.6\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"29.3\" y=\"144.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"66\" y=\"113.1\" font-size=\"13\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">80°</text><text x=\"161.9\" y=\"142.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"67.3\" y=\"-44\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><polygon points=\"361,71.3 220,20 246.3,269.9\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"374.1\" y=\"72\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"211.4\" y=\"14.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"243.4\" y=\"289.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text></svg>",
  secenekler: ["23","36","64","80"],
  dogru: 1,
  hatalar: ["x değerini açının ölçüsü sandın; açıyı bulmak için x'i ifadede yerine koymalısın.",null,"F açısını B açısıyla eşleştirdin; F köşesi C'nin karşılığıdır.","F açısını A açısıyla eşleştirdin; F köşesi C'nin karşılığıdır, A'nın değil."],
  aciklama: "Üçgenin iç açıları toplamı 180°'dir. Benzer üçgenlerde karşılık gelen açılar eşittir ve eşleşme harf sırasına göredir: ABC ~ DEF ise A ↔ D, B ↔ E, C ↔ F.\nAdım 1: Açıların toplamını yaz: 80 + (3x − 5) + (2x − 10) = 180. Buradan 5x + 65 = 180, x = 23.\nAdım 2: m(C) = 2 · 23 − 10 = 36°, m(B) = 3 · 23 − 5 = 64°.\nAdım 3: F köşesi C'nin karşılığı olduğundan m(F) = m(C) = 36°.\nSağlama: 80 + 64 + 36 = 180.\nCevap B."
},
{
  id: "mat-eb-342",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Kareli kâğıda çizilen K dik yamuğunun kenarları kare çizgileri üzerindedir, eğik kenarı ise iki köşeyi birleştirmektedir. Karelerin kenarı 1 birimdir. K yamuğunun, kenarları aynı oranda büyütülerek benzerlik oranı 3 olan yeni bir yamuk çizilecektir.\n**Yeni yamuğun çevresi kaç birimdir?**",
  gorsel: "<svg viewBox=\"-8 -8 128 80\" role=\"img\" aria-label=\"Kareli kâğıtta dik yamuk\"><polygon points=\"0,64 96,64 48,0 0,0\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"16\" y1=\"0\" x2=\"16\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"32\" y1=\"0\" x2=\"32\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"48\" y1=\"0\" x2=\"48\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"64\" y1=\"0\" x2=\"64\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"80\" y1=\"0\" x2=\"80\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"96\" y1=\"0\" x2=\"96\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"112\" y1=\"0\" x2=\"112\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"112\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"16\" x2=\"112\" y2=\"16\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"32\" x2=\"112\" y2=\"32\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"48\" x2=\"112\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"64\" x2=\"112\" y2=\"64\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"25.6\" y=\"36.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text></svg>",
  secenekler: ["18","21","44","54"],
  dogru: 3,
  hatalar: ["K şeklinin çevresini yazdın; sorulan, kenarları 3 katına çıkan yamuğun çevresidir.","Çevreye oranı ekledin (18 + 3); benzerlikte çevre oranla çarpılır.","Eğik kenarı 5 birimde bıraktın (3 · (6 + 4 + 3) + 5); eğik kenar da diğerleri gibi 3 katına çıkar.",null],
  aciklama: "Benzer çokgenlerde çevreler oranı benzerlik oranına eşittir.\nAdım 1: Kareli kâğıttan alt taban 6, sol kenar 4, üst taban 3 birimdir. Eğik kenar, 3 birim yatay ve 4 birim dikey ilerler; Pisagor'a göre 3^{2} + 4^{2} = 5^{2} olduğundan 5 birimdir.\nAdım 2: K'nin çevresi 6 + 4 + 3 + 5 = 18 birimdir.\nAdım 3: Oran 3 olduğundan yeni yamuğun çevresi 18 · 3 = 54 birimdir.\nSağlama: Yeni kenarlar 18, 12, 9, 15; toplam 54.\nCevap D."
},
{
  id: "mat-eb-343",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Kenarları 8 cm ve 6 cm olan dikdörtgen biçimli bir origami kâğıdı, AC köşegeni boyunca kesilerek iki üçgen parçaya ayrılıyor; bu iki parça birbirine eştir (ABC ≅ CDA).\n**İki parçanın çevreleri toplamı kaç santimetredir?**",
  gorsel: "<svg viewBox=\"17 -5 228 176\" role=\"img\" aria-label=\"Köşegeniyle kesilen dikdörtgen\"><polygon points=\"40,140 200,140 200,20 40,20\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"30.1\" y=\"155.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"120\" y=\"159\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"209.9\" y=\"155.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"220.7\" y=\"85\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><text x=\"209.9\" y=\"15.6\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"30.1\" y=\"15.6\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><line x1=\"40\" y1=\"140\" x2=\"200\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/></svg>",
  secenekler: ["48","28","24","14"],
  dogru: 0,
  hatalar: [null,"Dikdörtgenin çevresini buldun (8 + 6 + 8 + 6 = 28); köşegen parçaların ortak kenarı olarak iki parçanın da çevresine girer.","Yalnızca bir parçanın çevresini buldun; soruda iki parçanın çevreleri toplamı isteniyor.","Dikdörtgenin yarı çevresini buldun (8 + 6); soruda iki parçanın çevreleri toplamı isteniyor."],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşit olduğundan çevreler de eşittir. Dik üçgende dik kenarlarla hipotenüs arasında Pisagor bağıntısı vardır.\nAdım 1: Köşegen, dik üçgenin hipotenüsüdür: |AC|^{2} = 8^{2} + 6^{2} = 100 olduğundan |AC| = 10 cm.\nAdım 2: Bir parçanın çevresi 8 + 6 + 10 = 24 cm; eş olan diğer parçanın çevresi de 24 cm.\nAdım 3: Çevreler toplamı 24 + 24 = 48 cm.\nSık yapılan hata: Köşegeni unutup yalnızca dikdörtgenin kenarlarıyla çevre hesaplamak.\nCevap A."
},
{
  id: "mat-eb-344",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir okulda kütüphane binasının maketi yapılıyor. Maket, binaya benzerdir ve maketteki her uzunluk, binadaki karşılığının [[1|50]]'i kadardır. Maketin dikdörtgen biçimli ön cephesi 24 cm × 18 cm'dir.\n**Gerçek binanın ön cephesinin çevresi kaç metredir?**",
  gorsel: null,
  secenekler: ["4200","84","42","21"],
  dogru: 2,
  hatalar: ["Birimi metreye çevirmedin; 4200 santimetre = 42 metredir.","Maketin çevresini (84 cm) gerçek çevre sandın; maket oranı uygulanmadan sonuç yazıldı.",null,"Yalnızca iki kenarın toplamını buldun (12 + 9); çevre dört kenarın toplamıdır."],
  aciklama: "Maket ve bina benzerdir; maketteki uzunluklar gerçek uzunlukların [[1|50]]'idir. Yani gerçek uzunluk, maket uzunluğunun 50 katıdır.\nAdım 1: Gerçek cephenin kenarları 24 · 50 = 1200 cm ve 18 · 50 = 900 cm olur.\nAdım 2: Metreye çevir: 1200 cm = 12 m ve 900 cm = 9 m.\nAdım 3: Çevre = 2 · (12 + 9) = 42 m.\nSağlama: Maketin çevresi 84 cm, 84 · 50 = 4200 cm = 42 m.\nSık yapılan hata: Santimetreyi metreye çevirmeyi unutmak.\nCevap C."
},
{
  id: "mat-eb-345",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir reklam firması, üçgen biçimli iki tabela hazırlıyor ve ABC ~ DEF'dir. ABC tabelasının DEF tabelasına benzerlik oranı [[4|3]]'tür. ABC tabelasının çevresi 48 cm'dir.\n**DEF tabelasının çevresi kaç santimetredir?**",
  gorsel: null,
  secenekler: ["12","36","45","64"],
  dogru: 1,
  hatalar: ["Çevreyi oranın payına böldün (48 ÷ 4); oran kesirdir, çevreyi [[4|3]]'e bölmek gerekir.",null,"Çevreden oranın paydasını çıkardın (48 − 3); çevreler fark ile değil oranla ilişkilidir.","Oranı ters yorumladın (48 · [[4|3]]); ABC / DEF oranı [[4|3]] olduğundan DEF, ABC'den küçüktür."],
  aciklama: "ABC'nin DEF'ye benzerlik oranı [[4|3]] ise ABC'nin kenarları DEF'nin karşılık gelen kenarlarının [[4|3]] katıdır; yani ABC daha büyüktür. Çevreler oranı da [[4|3]]'tür.\nAdım 1: Çevre(ABC) / Çevre(DEF) = [[4|3]].\nAdım 2: Çevre(DEF) = 48 ÷ [[4|3]] = 48 · [[3|4]] = 36 cm.\nSağlama: 36 · [[4|3]] = 48 cm.\nSık yapılan hata: Oranı hangi şekle göre yazıldığına bakmadan çarpmak.\nCevap B."
},
{
  id: "mat-eb-346",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Kareli kâğıtta karelerin kenarı 1 birimdir. ABC üçgeni ve EF kenarı çizilmiştir. Esra, ABC ≅ EFG olacak biçimde G köşesini P, R, S, T noktalarından biri olarak seçecektir.\n**G köşesi hangi nokta olmalıdır?**",
  gorsel: "<svg viewBox=\"-7 -2 251 137\" role=\"img\" aria-label=\"Kareli kâğıtta ABC üçgeni ve EF kenarı\"><polygon points=\"20,96 92,96 20,42\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"20\" y1=\"24\" x2=\"20\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"38\" y1=\"24\" x2=\"38\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"56\" y1=\"24\" x2=\"56\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"74\" y1=\"24\" x2=\"74\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"92\" y1=\"24\" x2=\"92\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"110\" y1=\"24\" x2=\"110\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"128\" y1=\"24\" x2=\"128\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"146\" y1=\"24\" x2=\"146\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"164\" y1=\"24\" x2=\"164\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"182\" y1=\"24\" x2=\"182\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"200\" y1=\"24\" x2=\"200\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"218\" y1=\"24\" x2=\"218\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"236\" y1=\"24\" x2=\"236\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"24\" x2=\"236\" y2=\"24\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"42\" x2=\"236\" y2=\"42\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"60\" x2=\"236\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"78\" x2=\"236\" y2=\"78\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"96\" x2=\"236\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"146\" y1=\"96\" x2=\"218\" y2=\"96\" stroke=\"currentColor\" stroke-width=\"3\"/><circle cx=\"20\" cy=\"96\" r=\"3.5\" fill=\"currentColor\"/><text x=\"6\" y=\"121\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><circle cx=\"92\" cy=\"96\" r=\"3.5\" fill=\"currentColor\"/><text x=\"92\" y=\"123\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><circle cx=\"20\" cy=\"42\" r=\"3.5\" fill=\"currentColor\"/><text x=\"6\" y=\"47\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><circle cx=\"146\" cy=\"96\" r=\"3.5\" fill=\"currentColor\"/><text x=\"146\" y=\"123\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><circle cx=\"218\" cy=\"96\" r=\"3.5\" fill=\"currentColor\"/><text x=\"218\" y=\"123\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><circle cx=\"146\" cy=\"42\" r=\"3.5\" fill=\"currentColor\"/><text x=\"134\" y=\"39\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><circle cx=\"218\" cy=\"42\" r=\"3.5\" fill=\"currentColor\"/><text x=\"230\" y=\"39\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">P</text><circle cx=\"182\" cy=\"24\" r=\"3.5\" fill=\"currentColor\"/><text x=\"182\" y=\"19\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">S</text><circle cx=\"146\" cy=\"24\" r=\"3.5\" fill=\"currentColor\"/><text x=\"132\" y=\"15\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">T</text></svg>",
  secenekler: ["P noktası","R noktası","S noktası","T noktası"],
  dogru: 1,
  hatalar: ["P için |EG| = 5 ve |FG| = 3 olur; ABC ≅ EFG yazılışında B ↔ F, C ↔ G olduğundan |FG| = |BC| = 5 olmalıdır. Kenar uzunlukları aynı çıksa da köşeler yanlış eşleşir.",null,"S için |EG| ve |FG| kenarları tam sayı değildir; ABC'nin 3, 4, 5 birimlik kenarlarıyla eşleşmez.","T için |EG| = 4 olur, oysa |EG| = |CA| = 3 olmalıdır."],
  aciklama: "Eş üçgenlerde karşılık gelen kenarlar eşittir; ABC ≅ EFG yazılışında A ↔ E, B ↔ F, C ↔ G olur.\nAdım 1: Kareli kâğıttan |AB| = 4, |CA| = 3 birimdir; |BC| ise 3 ve 4 birimlik dik kenarlı üçgenin hipotenüsü olduğundan 5 birimdir.\nAdım 2: |EF| = |AB| = 4 uyuyor. G için |EG| = |CA| = 3 ve |FG| = |BC| = 5 olmalıdır.\nAdım 3: R noktası, E'nin 3 birim yukarısında; F'ye uzaklığı 3 ve 4 birimlik dik kenarlardan 5 birimdir. Yalnızca R uyar.\nSık yapılan hata: Kenar uzunlukları aynı çıksa da harf sırasına göre karşılık gelen kenarları kontrol etmemek.\nCevap B."
},
{
  id: "mat-eb-347",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Okul kulübü, KLM üçgeni biçimindeki amblemi büyüterek PRS amblemini elde ediyor (KLM ~ PRS). Amblemlerin bazı kenar uzunlukları santimetre cinsinden şekilde verilmiştir.\n**x kaçtır?**",
  gorsel: "<svg viewBox=\"-5 -35 549 233\" role=\"img\" aria-label=\"Benzer iki üçgen amblem\"><polygon points=\"30,110 100,110 109.8,12.5\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"8.3\" y=\"125.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"65\" y=\"129\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">(2x − 1) cm</text><text x=\"116.1\" y=\"133.3\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"119\" y=\"-4.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"52.2\" y=\"51.8\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><polygon points=\"516.7,41.3 385.1,-6.6 300,170\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"530.6\" y=\"45.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">P</text><text x=\"460.5\" y=\"-4.1\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">(3x + 1) cm</text><text x=\"379.8\" y=\"-14\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><text x=\"290.5\" y=\"185.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">S</text><text x=\"420\" y=\"130.2\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">18 cm</text></svg>",
  secenekler: ["10","7","5","3"],
  dogru: 3,
  hatalar: ["|PR| = 3x + 1 ifadesinin değerini (10) cevap yazdın; sorulan x'tir.","Farkla çözdün: |SP| − |MK| = 9 olduğundan |PR| = |KL| + 9 aldın (3x + 1 = 2x − 1 + 9 → x = 7); benzerlikte kenarlar orantılıdır, fark eklenmez.","x yerine |KL| = 2x − 1 ifadesinin değerini (5) cevap yazdın; sorulan x'tir.",null],
  aciklama: "Benzer üçgenlerde karşılık gelen kenarların oranı sabittir. KLM ~ PRS olduğundan K ↔ P, L ↔ R, M ↔ S eşleşir; |KL| ↔ |PR| ve |MK| ↔ |SP| olur.\nAdım 1: Sayıyla verilen çiftten oran: |SP| / |MK| = 18 / 9 = 2.\nAdım 2: |PR| = 2 · |KL| olduğundan 3x + 1 = 2 · (2x − 1) = 4x − 2.\nAdım 3: 3 = x bulunur.\nSağlama: |KL| = 2 · 3 − 1 = 5 ve |PR| = 3 · 3 + 1 = 10; 10 / 5 = 2.\nCevap D."
},
{
  id: "mat-eb-348",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Deniz, 24 cm × 36 cm boyutlarındaki dikdörtgen biçimli bir kartonu, kısa kenara paralel iki kesikle üç şeride ayırıyor (şekil). Kesikler uzun kenarı 12 cm'lik üç eş parçaya böler.\n**Oluşan şeritler için aşağıdakilerden hangisi doğrudur?**",
  gorsel: "<svg viewBox=\"-16 12 280 183\" role=\"img\" aria-label=\"Üç eş şeride bölünen karton\"><polygon points=\"40,20 256,20 256,164 40,164\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"112\" y1=\"20\" x2=\"112\" y2=\"164\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><line x1=\"184\" y1=\"20\" x2=\"184\" y2=\"164\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><text x=\"76\" y=\"183\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"148\" y=\"183\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"220\" y=\"183\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"32\" y=\"97\" font-size=\"14\" text-anchor=\"end\" fill=\"currentColor\">24 cm</text></svg>",
  secenekler: ["Şeritler birbirine eştir ancak asıl kartona benzer değildir.","Şeritler birbirine eştir ve asıl kartona benzerdir.","Şeritler birbirine benzerdir ancak birbirine eş değildir.","Şeritler birbirine eş değildir ve asıl kartona benzer değildir."],
  dogru: 0,
  hatalar: [null,"Şeritlerin kısa / uzun oranı 12 / 24 = [[1|2]], kartonunki 24 / 36 = [[2|3]]'tür; oranlar eşit olmadığı için şeritler kartona benzer değildir.","Şeritlerin üçü de 12 cm × 24 cm'dir; ölçüleri aynı olduğundan birbirine eştirler.","Üç şeritte karşılık gelen kenarlar ve açılar eşit olduğundan şeritler birbirine eştir."],
  aciklama: "Eş şekillerde karşılık gelen kenarlar eşittir; benzer şekillerde kenarlar orantılıdır ve açılar eşittir.\nAdım 1: Her şeridin ölçüleri 12 cm × 24 cm'dir; üçü de aynı olduğundan birbirine eştir.\nAdım 2: Şeridin kısa / uzun oranı 12 / 24 = [[1|2]]; kartonun oranı 24 / 36 = [[2|3]]. Bu oranlar eşit değildir.\nAdım 3: Şeritler kartona benzer değildir.\nSık yapılan hata: \"Parçalar küçük bir kopya\" diye kartona benzer saymak; kenar oranlarına bakmak gerekir.\nCevap A."
},
{
  id: "mat-eb-349",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Kareli kâğıda çizilen K merdiven biçimli şeklinin bütün açıları diktir ve karelerin kenarı 1 birimdir. Bir sticker firması bu şekli, benzerlik oranı 3 olacak biçimde büyütüp baskı yapacaktır.\n**Büyütülmüş şeklin çevresi kaç birimdir?**",
  gorsel: "<svg viewBox=\"-8 -8 96 64\" role=\"img\" aria-label=\"Kareli kâğıtta merdiven biçimli şekil\"><polygon points=\"0,48 0,0 16,0 16,16 48,16 48,32 80,32 80,48\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"16\" y1=\"0\" x2=\"16\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"32\" y1=\"0\" x2=\"32\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"48\" y1=\"0\" x2=\"48\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"64\" y1=\"0\" x2=\"64\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"80\" y1=\"0\" x2=\"80\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"80\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"16\" x2=\"80\" y2=\"16\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"32\" x2=\"80\" y2=\"32\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"48\" x2=\"80\" y2=\"48\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"19.2\" y=\"41.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text></svg>",
  secenekler: ["16","19","32","48"],
  dogru: 3,
  hatalar: ["K şeklinin çevresini yazdın; sorulan büyütülmüş şeklin çevresidir.","Çevreye oranı ekledin (16 + 3); benzerlikte çevre oranla çarpılır.","Oranı 2 aldın (16 · 2); verilen benzerlik oranı 3'tür.",null],
  aciklama: "Bütün açıları dik olan ve içe oyuk girmeyen merdiven biçimlerinde çevre, şekli saran dikdörtgenin çevresine eşittir. Benzer şekillerde çevre, benzerlik oranıyla çarpılır.\nAdım 1: K şekli 5 birim genişliğinde ve 3 birim yüksekliğindeki bir dikdörtgenin içine yerleşir.\nAdım 2: K'nin çevresi 2 · (5 + 3) = 16 birimdir.\nAdım 3: Oran 3 olduğundan yeni çevre 16 · 3 = 48 birimdir.\nSağlama: Yeni şekil 15 × 9'luk dikdörtgene sığar; 2 · (15 + 9) = 48.\nCevap D."
},
{
  id: "mat-eb-350",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir atölyede aynı kalıptan iki üçgen levha kesilmiştir (ABC ≅ DEF). Levhaların kenarları |AB| = (2x − 3) cm, |BC| = (x + 4) cm ve |DE| = (x + 5) cm olarak verilmiştir.\n**|EF| kaç santimetredir?**",
  gorsel: null,
  secenekler: ["16","13","12","8"],
  dogru: 2,
  hatalar: ["x yerine 2x yazdın; sorulan |EF| = |BC| = x + 4 uzunluğudur.","|DE| = |AB| = 13 cm değerini aldın; |EF| kenarı B ve C köşelerinin karşılığıdır, yani |BC|'ye eşittir.",null,"x değerini cevap yazdın; sorulan |EF| uzunluğudur."],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşittir. ABC ≅ DEF yazılışında A ↔ D, B ↔ E, C ↔ F olur; |AB| = |DE| ve |BC| = |EF| eşitlikleri geçerlidir.\nAdım 1: |AB| = |DE| olduğundan 2x − 3 = x + 5 ve x = 8 bulunur.\nAdım 2: |EF| = |BC| = x + 4 = 12 cm.\nSağlama: |AB| = 2 · 8 − 3 = 13 = |DE| = 8 + 5.\nCevap C."
},
{
  id: "mat-eb-351",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir cam atölyesi, aynı kalıptan iki ikizkenar yamuk biçimli cam parçası kesiyor (ABCD ≅ EFGH). ABCD parçasında AB // DC ve |AD| = |BC|'dir. Parçaların bazı kenar uzunlukları şekilde verilmiştir.\n**EFGH parçasının çevresi kaç santimetredir?**",
  gorsel: "<svg viewBox=\"4 12 369 91\" role=\"img\" aria-label=\"Eş iki ikizkenar yamuk\"><polygon points=\"30,72 142,72 118,40 54,40\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"17.5\" y=\"83.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"86\" y=\"91\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">14 cm</text><text x=\"154.5\" y=\"83.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"124.3\" y=\"33\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"86\" y=\"31\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"47.7\" y=\"33\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><polygon points=\"342,40 230,40 254,72 318,72\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"354.5\" y=\"39.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"217.5\" y=\"39.2\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"247.7\" y=\"90\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">G</text><text x=\"324.3\" y=\"90\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">H</text><text x=\"348.4\" y=\"74.8\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">5 cm</text></svg>",
  secenekler: ["32","38","44","64"],
  dogru: 0,
  hatalar: [null,"Karşılıklı kenarları eşit sanıp 2 · (14 + 5) yazdın; ABCD paralelkenar değil, yamuktur ve tabanları 14 ile 8'dir.","Yalnızca tabanları ikişer kez saydın (2 · (14 + 8)); bacaklar çevreye girer.","İki parçanın çevrelerini topladın (32 + 32); soru yalnızca EFGH parçasının çevresini sorar."],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşit olduğundan çevreler de eşittir. İkizkenar yamukta iki bacak birbirine eşittir.\nAdım 1: ABCD ≅ EFGH olduğundan E ↔ A ve H ↔ D; |AD| = |EH| = 5 cm.\nAdım 2: İkizkenar yamuk olduğundan |BC| = |AD| = 5 cm.\nAdım 3: Çevre = 14 + 8 + 5 + 5 = 32 cm; eş parçanın çevresi de 32 cm'dir.\nSık yapılan hata: İkinci bacağı saymayı unutmak.\nCevap A."
},
{
  id: "mat-eb-352",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir park yönetimi, beşgen biçimli iki süs havuzu yaptırıyor. Havuzlar birbirine benzerdir ve çevreleri 40 m ile 60 m'dir. Küçük havuzun bir kenarı 12 m'dir.\n**Büyük havuzda bu kenarın karşılığı kaç metredir?**",
  gorsel: null,
  secenekler: ["8","18","20","32"],
  dogru: 1,
  hatalar: ["Oranı ters uyguladın (12 · [[2|3]]); büyük havuzun kenarı küçüğünkinden büyük olmalıdır.",null,"Çevreler arasındaki farkı (60 − 40 = 20) cevap yazdın; kenar için oran kullanılmalıdır.","Çevre farkını kenara ekledin (12 + 20); benzerlikte kenarlar orantılanır, fark eklenmez."],
  aciklama: "Benzer çokgenlerde çevreler oranı, karşılık gelen kenarlar oranına eşittir.\nAdım 1: Benzerlik oranı = 60 / 40 = [[3|2]] (büyük / küçük).\nAdım 2: Büyük havuzdaki karşılık gelen kenar 12 · [[3|2]] = 18 m olur.\nSağlama: 18 / 12 = [[3|2]] = 60 / 40.\nSık yapılan hata: Çevre farkını kenara eklemek.\nCevap B."
},
{
  id: "mat-eb-353",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir matematik öğretmeni, benzerlik ve eşlikle ilgili dört cümle yazmış ve öğrencilerden yanlış olanı bulmalarını istemiştir.\n**Aşağıdakilerden hangisi __yanlıştır__?**",
  gorsel: null,
  secenekler: ["Benzerlik oranı 1 olan iki çokgen birbirine eştir.","ABC'nin DEF'ye benzerlik oranı 3 ise DEF'nin ABC'ye benzerlik oranı [[1|3]]'tür.","Benzer iki çokgenin çevreleri oranı, benzerlik oranına eşittir.","Karşılık gelen açıları eşit olan iki dörtgen her zaman benzerdir."],
  dogru: 3,
  hatalar: ["Bu ifade doğrudur; oran 1 ise karşılık gelen kenarlar eşit olur, açılar zaten eşittir, yani çokgenler eştir.","Bu ifade doğrudur; oranın yönü değişince oran çarpmaya göre tersine döner.","Bu ifade doğrudur; kenarların hepsi aynı oranda değiştiği için kenarların toplamı olan çevre de aynı oranda değişir.",null],
  aciklama: "Benzer çokgenlerde karşılık gelen açılar eşit ve karşılık gelen kenarlar orantılıdır. İki şart birlikte aranır; yalnızca birinin sağlanması benzerlik için yetmez.\nAdım 1: Oran 1 ise karşılık gelen kenarlar eşittir; açılar zaten eşit olduğundan çokgenler eştir (A doğru).\nAdım 2: Oran hangi şekle göre yazıldığına bağlıdır; 3 ise ters sırada [[1|3]] olur (B doğru).\nAdım 3: Çevre kenarların toplamıdır; kenarlar aynı oranda değiştiğinden çevreler oranı da benzerlik oranına eşittir (C doğru).\nAdım 4: Yalnızca açıların eşit olması yetmez. 2 cm × 4 cm ve 2 cm × 6 cm'lik iki dikdörtgenin bütün açıları 90°'dir; ama kenar oranları aynı değildir (D yanlış).\nSık yapılan hata: Açılar eşit diye şekilleri benzer saymak; kenarların orantılı olup olmadığına da bakılmalıdır.\nCevap D."
},
{
  id: "mat-eb-354",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 3,
  soru: "Bir tişört baskı atölyesi, kenarları 6 cm ve 9 cm olan dikdörtgen biçimli bir deseni bozmadan büyüterek çevresi 90 cm olan bir baskı hazırlıyor. Büyütülen baskı, desene benzerdir.\n**Büyütülen baskının kısa kenarı kaç santimetredir?**",
  gorsel: null,
  secenekler: ["18","27","30","45"],
  dogru: 0,
  hatalar: [null,"Büyütülen baskının uzun kenarını buldun (9 · 3); sorulan kısa kenardır.","Küçük desenin çevresini (30 cm) cevap yazdın; soru büyütülen baskının kısa kenarını sorar.","Çevrenin yarısını (90 ÷ 2) kısa kenar sandın; bu değer iki kenarın toplamıdır."],
  aciklama: "Benzer çokgenlerde çevreler oranı benzerlik oranına eşittir. Önce oranı çevrelerden bul, sonra kenarı oranla çarp.\nAdım 1: Desenin çevresi 2 · (6 + 9) = 30 cm.\nAdım 2: Benzerlik oranı 90 / 30 = 3.\nAdım 3: Kısa kenar 6 · 3 = 18 cm (uzun kenar 9 · 3 = 27 cm).\nSağlama: 2 · (18 + 27) = 90.\nCevap A."
},
{
  id: "mat-eb-355",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 3,
  soru: "Bir mozaik atölyesinde aynı kalıptan iki çokgen parça kesilmiştir; parçalar birbirine eştir. Bu parçaların çevreleri santimetre cinsinden (3x + 7) ve (5x − 9) olarak verilmiştir.\n**Parçalardan birinin çevresi kaç santimetredir?**",
  gorsel: null,
  secenekler: ["62","40","31","8"],
  dogru: 2,
  hatalar: ["İki çevreyi topladın; soru parçalardan birinin çevresini sorar.","x yerine 5x değerini aldın (5 · 8); çevre 5x − 9 = 31'dir.",null,"x değerini çevre sandın; çevreyi bulmak için x'i ifadelerden birinde yerine koymalısın."],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşit olduğundan çevreler de eşittir.\nAdım 1: Çevreleri eşitle: 3x + 7 = 5x − 9.\nAdım 2: 16 = 2x ve x = 8 bulunur.\nAdım 3: Çevre = 3 · 8 + 7 = 31 cm.\nSağlama: 5 · 8 − 9 = 31; iki çevre de eşit çıktı.\nCevap C."
},
{
  id: "mat-eb-356",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Okul müzikali için üçgen biçimli bir dekor parçası (ABC) büyütülerek DEF dekoru yapılıyor ve ABC ~ DEF'dir. Dekorların bazı kenar uzunlukları santimetre cinsinden şekilde verilmiştir.\n**DEF dekorunun |DE| kenarı kaç santimetredir?**",
  gorsel: "<svg viewBox=\"15 -179 370 340\" role=\"img\" aria-label=\"Benzer iki üçgen\"><polygon points=\"40,120 96,120 97.8,8\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"28\" y=\"132.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"68\" y=\"139\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">x</text><text x=\"105.8\" y=\"135.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"117.7\" y=\"69.3\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"101.2\" y=\"-0.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><polygon points=\"190,130 330,130 334.4,-150\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"178\" y=\"142.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"260\" y=\"149\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">(x + 6) cm</text><text x=\"339.8\" y=\"145.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"356.9\" y=\"-4.6\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">20 cm</text><text x=\"337.8\" y=\"-158\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text></svg>",
  secenekler: ["4","10","12","15"],
  dogru: 1,
  hatalar: ["x değerini buldun ama |DE| = x + 6 ifadesinin değerini hesaplamadın; sorulan x değil |DE|'dir.",null,"|EF| ile |BC| arasındaki farkı (20 − 8) cevap yazdın; kenar uzunluğu oranla bulunur.","Oranı yalnızca 6'ya uyguladın (6 · [[5|2]]); x + 6 ifadesinin tamamı oranla ilişkilidir."],
  aciklama: "Benzer üçgenlerde karşılık gelen kenarların oranı sabittir. ABC ~ DEF olduğundan |AB| ↔ |DE| ve |BC| ↔ |EF| olur.\nAdım 1: Sayıyla verilen çiftten oran: 20 / 8 = [[5|2]].\nAdım 2: |DE| = |AB| · [[5|2]] olduğundan x + 6 = [[5|2]] · x. Her iki yanı 2 ile çarp: 2x + 12 = 5x ve x = 4.\nAdım 3: |DE| = x + 6 = 10 cm.\nSağlama: 10 / 4 = [[5|2]] = 20 / 8.\nCevap B."
},
{
  id: "mat-eb-357",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir pencere ustası, kenarları 12 dm ve 15 dm olan dikdörtgen biçimli bir pencere camına benzer yeni bir cam kestirecektir. Yeni camın bir kenarı 20 dm, diğer kenarı a dm olacaktır. Yeni camın hangi kenarının eski camın hangi kenarına karşılık geleceği belli değildir.\n**a'nın alabileceği değerlerin toplamı kaçtır?**",
  gorsel: null,
  secenekler: ["16","25","41","400"],
  dogru: 2,
  hatalar: ["Yalnızca 20 dm kenarının 15 dm kenarına karşılık geldiği durumu buldun; 20 dm kenar 12 dm kenarın karşılığı da olabilir.","Yalnızca 20 dm kenarının 12 dm kenarına karşılık geldiği durumu buldun; 20 dm kenar 15 dm kenarın karşılığı da olabilir.",null,"İki değeri toplamak yerine çarptın (16 · 25); sorulan değerlerin toplamıdır."],
  aciklama: "Benzer dikdörtgenlerde kısa kenar kısa kenara, uzun kenar uzun kenara karşılık gelir; ama 20 dm kenarının kısa mı uzun mu olduğu belli değildir. İki durum incelenir.\nAdım 1: 20 dm kenarı kısa kenar ise 12 dm kenarının karşılığıdır; oran 20 / 12 = [[5|3]] olur ve a = 15 · [[5|3]] = 25 dm.\nAdım 2: 20 dm kenarı uzun kenar ise 15 dm kenarının karşılığıdır; oran 20 / 15 = [[4|3]] olur ve a = 12 · [[4|3]] = 16 dm.\nAdım 3: Her iki durum da geçerlidir (a = 25 iken 20 dm kısa, a = 16 iken 20 dm uzun kenar olur). Toplam 25 + 16 = 41.\nSağlama: 20 / 25 = [[4|5]] = 12 / 15 ve 16 / 20 = [[4|5]] = 12 / 15.\nCevap C."
},
{
  id: "mat-eb-358",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir matbaa, kenarları 12 cm ve 20 cm olan dikdörtgen biçimli bir afişe benzer afişler basacaktır. Yeni afişlerin kenar uzunlukları santimetre cinsinden tam sayı olacak, kısa kenarı en az 15 cm ve uzun kenarı en fazla 75 cm olacaktır.\n**Bu koşullara uyan kaç farklı boyutta afiş basılabilir?**",
  gorsel: null,
  secenekler: ["10","11","12","15"],
  dogru: 1,
  hatalar: ["m değerlerini 5 ile 15 arasında sayarken fark aldın (15 − 5); her iki uç da dahildir, 11 değer vardır.",null,"Alt sınırı bir eksik aldın (m = 4 için kısa kenar 12 cm olur ve 15 cm'den küçüktür); m en az 5 olmalıdır.","Yalnızca uzun kenar koşuluna baktın (75 ÷ 5 = 15); kısa kenarın en az 15 cm olması koşulunu unuttun."],
  aciklama: "Benzer dikdörtgenin kısa / uzun oranı 12 / 20 = [[3|5]]'tir. Kenarlar tam sayı olduğundan kısa kenar 3m, uzun kenar 5m biçiminde yazılır (m pozitif tam sayı).\nAdım 1: Kısa kenar en az 15 cm: 3m ≥ 15 ve m ≥ 5.\nAdım 2: Uzun kenar en fazla 75 cm: 5m ≤ 75 ve m ≤ 15.\nAdım 3: m = 5, 6, …, 15 değerlerini alır; 15 − 5 + 1 = 11 farklı boyut.\nSık yapılan hata: Uç değerlerden birini saymamak ya da kısa kenar koşulunu unutmak.\nCevap B."
},
{
  id: "mat-eb-359",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir yelken kulübü, kenarları 6 m, 8 m ve 12 m olan üçgen biçimli bir flamaya benzer flamalar hazırlayacaktır. Yeni flamaların kenar uzunlukları metre cinsinden tam sayı olacak ve çevreleri 40 m'den fazla olacaktır.\n**Bu koşullara uyan flamalardan en küçük çevreli olanın çevresi kaç metredir?**",
  gorsel: null,
  secenekler: ["52","40","39","26"],
  dogru: 0,
  hatalar: [null,"Çevrenin tam 40 olmasını istedin; 13 · m = 40 için m tam sayı değildir ve çevre 40'tan fazla olmalıdır.","m = 3 durumunu seçtin; çevre 13 · 3 = 39 metre olur ve 40 m'den fazla değildir.","m = 2 durumunu seçtin; çevre 13 · 2 = 26 metre olur ve 40 m'den fazla değildir."],
  aciklama: "ABC üçgeninin kenarları 6 : 8 : 12 = 3 : 4 : 6 oranındadır. Benzer üçgenlerin kenarları 3m, 4m, 6m biçiminde yazılır (m pozitif tam sayı); çevre 13m olur.\nAdım 1: Çevre 40'tan fazla olmalı: 13m > 40, yani m > 3,07...; m tam sayı olduğundan m ≥ 4.\nAdım 2: En küçük çevre için m = 4 alınır.\nAdım 3: Çevre 13 · 4 = 52 m olur (kenarlar 12, 16, 24 m).\nSağlama: 13 · 3 = 39 < 40 olduğundan m = 3 yetmez.\nCevap A."
},
{
  id: "mat-eb-360",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Bir seramik ustası, ikizkenar yamuk biçimli ABCD karosunu büyüterek EFGH karosunu yapıyor ve ABCD ~ EFGH'dir. İkizkenar yamuk ABCD'de AB // DC ve |AD| = |BC|'dir. ABCD karosunda m(A) = (2x + 25)° ve m(D) = (3x + 5)°'dir.\n**EFGH karosunda m(F) kaç derecedir?**",
  gorsel: "<svg viewBox=\"15 3 428 148\" role=\"img\" aria-label=\"Benzer iki ikizkenar yamuk\"><polygon points=\"40,124 152,124 128,60 64,60\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"28.5\" y=\"137.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"163.5\" y=\"137.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"136\" y=\"54\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"56\" y=\"54\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><polygon points=\"250,126 418,126 382,30 286,30\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"238.5\" y=\"139.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"429.5\" y=\"139.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"396.6\" y=\"116.2\" font-size=\"13\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">?</text><text x=\"390\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">G</text><text x=\"278\" y=\"24\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">H</text></svg>",
  secenekler: ["30","85","95","150"],
  dogru: 1,
  hatalar: ["x değerini açının ölçüsü sandın; açıyı bulmak için x'i ifadede yerine koymalısın.",null,"F açısını D açısıyla eşleştirdin (95°); F köşesi B'nin karşılığıdır ve ikizkenar yamukta m(B) = m(A) olur.","x değerini (30) 180°'den çıkardın; açıyı bulmak için x'i ifadelerde yerine koymak gerekir."],
  aciklama: "Paralel iki kenar arasındaki komşu açıların toplamı 180°'dir. İkizkenar yamukta aynı tabana komşu açılar eşittir. Benzer çokgenlerde karşılık gelen açılar eşittir: ABCD ~ EFGH ise A ↔ E, B ↔ F, C ↔ G, D ↔ H.\nAdım 1: AB // DC olduğundan m(A) + m(D) = 180°: (2x + 25) + (3x + 5) = 180, 5x + 30 = 180 ve x = 30.\nAdım 2: m(A) = 2 · 30 + 25 = 85°, m(D) = 3 · 30 + 5 = 95°.\nAdım 3: İkizkenar yamukta m(B) = m(A) = 85° olur; F köşesi B'nin karşılığı olduğundan m(F) = 85°.\nSağlama: 85° + 95° = 180°.\nCevap B."
},
{
  id: "mat-eb-361",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Bir okul tiyatrosunda dörtgen biçimli ABCD dekoru, aynı biçimde büyütülerek PRST dekoru yapılıyor (ABCD ~ PRST). PRST dekoru şekilde döndürülmüş olarak çizilmiştir. Bazı kenar uzunlukları santimetre cinsinden verilmiştir.\n**|ST| + |TP| toplamı kaç santimetredir?**",
  gorsel: "<svg viewBox=\"-4 -9 487 191\" role=\"img\" aria-label=\"Benzer iki dörtgen, ikincisi döndürülmüş\"><polygon points=\"50,150 106,150 84.3,68.9 30,113.1\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"42.8\" y=\"167.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"78\" y=\"169\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"117.1\" y=\"164\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"120.5\" y=\"107.6\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"88.6\" y=\"61\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"41.7\" y=\"77.1\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">10 cm</text><text x=\"16.3\" y=\"115.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"19.7\" y=\"147.5\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><polygon points=\"402.7,20 330,62 419.1,151.1 456.4,53\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"402.9\" y=\"11.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">P</text><text x=\"316.1\" y=\"65.7\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><text x=\"356.7\" y=\"129.4\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">18 cm</text><text x=\"422\" y=\"170.3\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">S</text><text x=\"469.7\" y=\"53.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">T</text></svg>",
  secenekler: ["15","16","21","24"],
  dogru: 3,
  hatalar: ["Yalnızca |ST| kenarını buldun (10 · [[3|2]]); |TP| kenarı da toplama girer.","ABCD'nin |CD| + |DA| toplamını (10 + 6) buldun; PRST büyütülmüş olduğundan karşılık gelen kenarlar oranla çarpılmalıdır.","Kenarları yazılış sırasına göre değil de konumlarına bakarak eşledin (|ST| ↔ |DA|, |TP| ↔ |AB|); doğru eşleme S ↔ C, T ↔ D, P ↔ A ile yapılır.",null],
  aciklama: "Benzer çokgenlerde karşılık gelen köşeler yazılış sırasına göre eşleşir: ABCD ~ PRST ise A ↔ P, B ↔ R, C ↔ S, D ↔ T olur. Şeklin döndürülmüş olması eşleşmeyi değiştirmez.\nAdım 1: |BC| ↔ |RS| olduğundan oran 18 / 12 = [[3|2]].\nAdım 2: |ST| ↔ |CD| = 10 cm: |ST| = 10 · [[3|2]] = 15 cm. |TP| ↔ |DA| = 6 cm: |TP| = 6 · [[3|2]] = 9 cm.\nAdım 3: Toplam 15 + 9 = 24 cm.\nSağlama: |PR| = 8 · [[3|2]] = 12; çevre 12 + 18 + 15 + 9 = 54 = 36 · [[3|2]].\nCevap D."
},
{
  id: "mat-eb-362",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "ABC dik üçgeninde B köşesi diktir, |AB| = 6 cm ve |BC| = 8 cm'dir. DEF üçgeni ABC'ye benzerdir (ABC ~ DEF) ve E köşesi diktir. DEF üçgeninin dik açının karşısındaki kenarı |DF| = 25 cm'dir.\n**DEF üçgeninin çevresi kaç santimetredir?**",
  gorsel: "<svg viewBox=\"-5 -13 402 160\" role=\"img\" aria-label=\"Benzer iki dik üçgen\"><polygon points=\"40,68 40,110 96,110\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"33.7\" y=\"61\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"19.3\" y=\"94\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">6 cm</text><text x=\"30.1\" y=\"125.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"68\" y=\"129\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"109.3\" y=\"119.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><polygon points=\"40,110 40,101 49,101 49,110\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><polygon points=\"230,15 230,120 370,120\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"223.7\" y=\"8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"220.1\" y=\"135.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"383.3\" y=\"129.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"314.4\" y=\"53.3\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">25 cm</text><polygon points=\"230,120 230,108 242,108 242,120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>",
  secenekler: ["60","35","25","24"],
  dogru: 0,
  hatalar: [null,"Yalnızca iki dik kenarın toplamını (15 + 20) buldun; hipotenüs de çevreye girer.","Soruda verilen |DF| = 25 cm değerini cevap yazdın; istenen DEF'nin çevresidir.","ABC'nin çevresini (6 + 8 + 10) cevap yazdın; DEF büyütülmüş üçgendir."],
  aciklama: "Dik üçgende dik kenarların kareleri toplamı hipotenüsün karesine eşittir. Benzer üçgenlerde çevreler oranı, benzerlik oranına eşittir.\nAdım 1: |AC|^{2} = 6^{2} + 8^{2} = 100 olduğundan |AC| = 10 cm ve ABC'nin çevresi 6 + 8 + 10 = 24 cm.\nAdım 2: |DF| ↔ |AC|: oran 25 / 10 = [[5|2]].\nAdım 3: DEF'nin çevresi 24 · [[5|2]] = 60 cm.\nSağlama: Dik kenarlar 6 · [[5|2]] = 15 ve 8 · [[5|2]] = 20; 15 + 20 + 25 = 60.\nCevap A."
},
{
  id: "mat-eb-363",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "ABC üçgeninin kenar uzunlukları |AB| = 6 cm, |BC| = 10 cm ve |CA| = x cm'dir; x bir tam sayıdır. DEF üçgeni ABC'ye benzerdir (ABC ~ DEF) ve |DE| = 9 cm, |EF| = 15 cm, |FD| = y cm'dir; y de bir tam sayıdır.\n**Bu koşullara uyan kaç farklı y değeri vardır?**",
  gorsel: null,
  secenekler: ["17","11","7","5"],
  dogru: 3,
  hatalar: ["Üçgen eşitsizliğini doğrudan DEF'ye uygulayıp 6 < y < 24 aralığındaki 17 sayıyı saydın; benzerlikte y, x'e bağlıdır (y = [[3|2]]x).","x için bulunan 11 tam sayıyı (5, 6, …, 15) saydın; y = [[3|2]]x'in de tam sayı olması gerektiğini atladın.","x'in alabileceği değerleri 4 ile 16 dahil çift sayılar sandın; üçgen eşitsizliğinde uç değerler alınamaz (4 < x < 16).",null],
  aciklama: "Üçgen eşitsizliğinde bir kenar, diğer ikisinin farkından büyük, toplamından küçüktür. Benzer üçgenlerde karşılık gelen kenarların oranı sabittir.\nAdım 1: ABC için 10 − 6 < x < 10 + 6, yani 4 < x < 16; x = 5, 6, …, 15.\nAdım 2: Oran |DE| / |AB| = 9 / 6 = [[3|2]] (|EF| / |BC| = 15 / 10 ile tutarlıdır). Buradan y = [[3|2]] · x olur.\nAdım 3: y tam sayı olacağından x çift olmalıdır: x = 6, 8, 10, 12, 14. Bu 5 değer 5 farklı y verir (9, 12, 15, 18, 21).\nCevap D."
},
{
  id: "mat-eb-364",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Aynı biçimli iki L şekli, farklı kareli kâğıtlara çizilmiştir. K şekli, karelerin kenarı 1 cm olan kâğıda; L şekli ise karelerin kenarı 2 cm olan kâğıda çizilmiştir. İki kâğıtta da şekil 5 kare genişliğinde ve 4 kare yüksekliğindedir ve bütün açıları diktir. Bu şekillere benzer bir M şekli de karelerin kenarı bilinmeyen bir kâğıda çizilmiştir; M şekli de 5 kare genişliğinde ve 4 kare yüksekliğindedir ve çevresi L şeklinin çevresinden 18 cm fazladır.\n**M şeklinin çizildiği kâğıtta karelerin kenarı kaç santimetredir?**",
  gorsel: "<svg viewBox=\"-8 -29 286 161\" role=\"img\" aria-label=\"İki farklı kareli kâğıtta aynı biçimli şekiller\"><polygon points=\"10,10 20,10 20,40 60,40 60,50 10,50\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><polygon points=\"150,20 170,20 170,80 250,80 250,100 150,100\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"10\" y1=\"0\" x2=\"10\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"20\" y1=\"0\" x2=\"20\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"30\" y1=\"0\" x2=\"30\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"40\" y1=\"0\" x2=\"40\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"50\" y1=\"0\" x2=\"50\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"60\" y1=\"0\" x2=\"60\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"70\" y1=\"0\" x2=\"70\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"0\" x2=\"70\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"10\" x2=\"70\" y2=\"10\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"20\" x2=\"70\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"30\" x2=\"70\" y2=\"30\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"40\" x2=\"70\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"0\" y1=\"50\" x2=\"70\" y2=\"50\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"35\" y=\"70\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">1 cm</text><line x1=\"130\" y1=\"0\" x2=\"130\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"150\" y1=\"0\" x2=\"150\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"170\" y1=\"0\" x2=\"170\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"190\" y1=\"0\" x2=\"190\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"210\" y1=\"0\" x2=\"210\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"230\" y1=\"0\" x2=\"230\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"250\" y1=\"0\" x2=\"250\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"270\" y1=\"0\" x2=\"270\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"0\" x2=\"270\" y2=\"0\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"20\" x2=\"270\" y2=\"20\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"40\" x2=\"270\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"60\" x2=\"270\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"80\" x2=\"270\" y2=\"80\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><line x1=\"130\" y1=\"100\" x2=\"270\" y2=\"100\" stroke=\"currentColor\" stroke-width=\"1\" opacity=\"0.25\"/><text x=\"200\" y=\"120\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">2 cm</text><text x=\"35\" y=\"-8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"200\" y=\"-8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text></svg>",
  secenekler: ["1","2","3","6"],
  dogru: 2,
  hatalar: ["K şeklinin kâğıdındaki kare kenarını (1 cm) yazdın; M şeklinin çevresi daha büyük olduğu için daha büyük karelere çizilmiştir.","L şeklinin kâğıdındaki kare kenarını (2 cm) yazdın; M'nin çevresi L'ninkinden 18 cm fazla olduğundan karesi 2 cm'den büyüktür.",null,"Çevreyi 5 + 4 = 9 kare kenarına bölerek hesapladın (54 ÷ 9 = 6); çevre iki genişlik ve iki yükseklikten oluşur, yani 2 · (5 + 4) = 18 kare kenarıdır."],
  aciklama: "Kareli kâğıtta uzunluk, kare sayısıyla kare kenarının çarpımıdır. Bütün açıları dik olan bu tür L biçimlerinde çevre, şekli saran dikdörtgenin çevresine eşittir. Kare kenarı s cm ise çevre 18 · s cm olur.\nAdım 1: Şekiller 5 kare genişliğinde ve 4 kare yüksekliğinde olduğundan çevreleri 2 · (5 + 4) = 18 kare kenarıdır.\nAdım 2: L şeklinde kare kenarı 2 cm olduğundan L'nin çevresi 18 · 2 = 36 cm; M'nin çevresi 36 + 18 = 54 cm.\nAdım 3: M'de 18 · s = 54 olduğundan s = 3 cm.\nSağlama: M, 15 cm × 12 cm'lik dikdörtgene sığar; çevresi 2 · (15 + 12) = 54 cm. K, L, M şekillerinin benzerlik oranları 1 : 2 : 3 ve çevreleri 18, 36, 54 cm olur.\nCevap C."
},
{
  id: "mat-eb-365",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir belediye, üçgen biçimli iki çiçek tarhı yapıyor. Tarhlar benzerdir ve büyük tarhın küçük tarha benzerlik oranı [[5|3]]'tür. Büyük tarhın çevresi, küçük tarhın çevresinden 30 m fazladır.\n**Küçük tarhın çevresi kaç metredir?**",
  gorsel: null,
  secenekler: ["18","45","75","90"],
  dogru: 1,
  hatalar: ["Çevre farkını küçültme oranıyla çarptın (30 · [[3|5]]); fark, çevre değildir ve çevre oranından denklem kurulmalıdır.",null,"Büyük tarhın çevresini buldun; soru küçük tarhın çevresini sorar.","Çevre farkını oranın paydasıyla çarptın (30 · 3); çevreleri oranla ilişkilendirmeden sonuç yazıldı."],
  aciklama: "Benzer çokgenlerde çevreler oranı benzerlik oranına eşittir. Oran [[5|3]] ise çevreleri 5t ve 3t olarak yazabiliriz.\nAdım 1: Küçük tarhın çevresi 3t, büyük tarhın çevresi 5t olsun.\nAdım 2: Fark 5t − 3t = 2t = 30 olduğundan t = 15.\nAdım 3: Küçük tarhın çevresi 3 · 15 = 45 m olur.\nSağlama: Büyük tarhın çevresi 5 · 15 = 75 m; 75 − 45 = 30 ve 75 / 45 = [[5|3]].\nCevap B."
},
{
  id: "mat-eb-366",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Bir tasarımcı, ikizkenar yamuk biçimli KLMN ayna çerçevesini büyütülmüş PRST çerçevesine dönüştürüyor (KLMN ~ PRST). KLMN'de KL // NM, |KL| = 20 cm, |NM| = 8 cm'dir ve çevresi 52 cm'dir. PRST'de |PR| = 30 cm'dir.\n**PRST çerçevesinin bacaklarından biri kaç santimetredir?**",
  gorsel: "<svg viewBox=\"14 -18 422 152\" role=\"img\" aria-label=\"Benzer iki ikizkenar yamuk\"><polygon points=\"40,102.4 160,102.4 124,40 76,40\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"27.9\" y=\"114.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">K</text><text x=\"100\" y=\"121.4\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">20 cm</text><text x=\"172.1\" y=\"114.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">L</text><text x=\"131\" y=\"33.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">M</text><text x=\"100\" y=\"31\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"69\" y=\"33.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">N</text><polygon points=\"230,103.5 410,103.5 356,10 284,10\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"217.9\" y=\"116\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">P</text><text x=\"320\" y=\"122.5\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">30 cm</text><text x=\"422.1\" y=\"116\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">R</text><text x=\"363\" y=\"3.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">S</text><text x=\"277\" y=\"3.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">T</text></svg>",
  secenekler: ["26","22","18","12"],
  dogru: 2,
  hatalar: ["Çevrenin yarısını (52 ÷ 2) bacak sandın; bacak, çevreden tabanlar çıkarılıp ikiye bölünerek bulunur.","Farkla çözdün: |PR| − |KL| = 10 olduğundan bacağa 10 ekledin (12 + 10); benzerlikte kenarlar orantılanır.",null,"KLMN'nin bacak uzunluğunu buldun; PRST büyütülmüş olduğundan bacak da büyür."],
  aciklama: "İkizkenar yamukta iki bacak eşittir. Benzer çokgenlerde karşılık gelen kenarlar aynı oranda büyür: KLMN ~ PRST ise |KL| ↔ |PR|, bacaklar da bacaklara karşılık gelir.\nAdım 1: KLMN'nin bacakları: (52 − 20 − 8) ÷ 2 = 12 cm.\nAdım 2: Oran |PR| / |KL| = 30 / 20 = [[3|2]].\nAdım 3: PRST'nin bacağı 12 · [[3|2]] = 18 cm.\nSağlama: PRST'nin çevresi 30 + 12 + 18 + 18 = 78 = 52 · [[3|2]].\nCevap C."
},
{
  id: "mat-eb-367",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir sergi atölyesi, kenarları 60 cm ve 80 cm olan dikdörtgen biçimli bir halı desenini önce [[3|4]] oranında küçülterek bir sergi modeli yapıyor, ardından bu modeli [[8|5]] oranında büyüterek bir baskı hazırlıyor. Her işlemde desenin bütün kenarları aynı oranda değişiyor.\n**Son baskının çevresi, ilk desenin çevresinden kaç santimetre fazladır?**",
  gorsel: null,
  secenekler: ["56","70","280","336"],
  dogru: 0,
  hatalar: [null,"Yalnızca ilk işlemi dikkate alıp çevre farkını buldun (280 − 210); iki işlemin oranı çarpılır ve son baskı ilk desenle karşılaştırılır.","İlk desenin çevresini (280) cevap yazdın; soru, çevreler arasındaki farkı sorar.","Son baskının çevresini (336) cevap yazdın; soru, bunun ilk desenin çevresinden ne kadar fazla olduğunu sorar."],
  aciklama: "Art arda uygulanan benzerlik oranları çarpılır. Benzer çokgenlerde çevreler oranı da benzerlik oranına eşittir.\nAdım 1: Toplam oran = [[3|4]] · [[8|5]] = [[24|20]] = [[6|5]].\nAdım 2: İlk desenin çevresi 2 · (60 + 80) = 280 cm.\nAdım 3: Son baskının çevresi 280 · [[6|5]] = 336 cm; fark 336 − 280 = 56 cm.\nSağlama: Adım adım git: 60 → 45 → 72 ve 80 → 60 → 96; çevre 2 · (72 + 96) = 336 cm.\nSık yapılan hata: Yalnızca bir işlemin oranını uygulamak ya da çevrenin kendisini fark sanmak.\nCevap A."
},
{
  id: "mat-eb-368",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "ABC üçgeninin kenar uzunlukları 6 cm, 8 cm ve 10 cm'dir. DEF üçgeni ABC'ye benzerdir ve DEF üçgeninin en kısa kenarı 9 cm'dir. DEF üçgeninin çevresi santimetre cinsinden (4x + 4) olarak verilmiştir.\n**x kaçtır?**",
  gorsel: null,
  secenekler: ["3","8","9","36"],
  dogru: 1,
  hatalar: ["Oranı ters kullandın (24 · [[2|3]] = 16 ve 4x + 4 = 16); DEF büyütülmüş üçgendir, çevresi ABC'den büyüktür.",null,"En kısa kenar olan 9 cm değerini x sandın; x, çevre ifadesinden bulunur.","DEF'nin çevresini (36 cm) cevap yazdın; x, 4x + 4 = 36 denkleminin çözümüdür."],
  aciklama: "Benzer üçgenlerde en kısa kenar en kısa kenara karşılık gelir; çevreler oranı benzerlik oranına eşittir.\nAdım 1: ABC'nin en kısa kenarı 6 cm, DEF'ninki 9 cm; oran 9 / 6 = [[3|2]].\nAdım 2: ABC'nin çevresi 6 + 8 + 10 = 24 cm; DEF'nin çevresi 24 · [[3|2]] = 36 cm.\nAdım 3: 4x + 4 = 36 denkleminden 4x = 32 ve x = 8.\nSağlama: 4 · 8 + 4 = 36.\nCevap B."
},
{
  id: "mat-eb-369",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "ABC dik üçgeninde B köşesi diktir, |AB| = 8 cm ve |AC| = 17 cm'dir. DEF üçgeni ABC'ye benzerdir (ABC ~ DEF), E köşesi diktir ve DEF üçgeninin çevresi 60 cm'dir.\n**|DE| = x kaç santimetredir?**",
  gorsel: "<svg viewBox=\"5 9 450 138\" role=\"img\" aria-label=\"Benzer iki dik üçgen\"><polygon points=\"50,44 50,100 155,100\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"42.8\" y=\"37.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"29.3\" y=\"77\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">8 cm</text><text x=\"40.1\" y=\"115.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"168.6\" y=\"108.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"112.9\" y=\"57.4\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">17 cm</text><polygon points=\"50,100 50,91 59,91 59,100\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><polygon points=\"270,36 270,120 427.5,120\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"262.8\" y=\"29.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><text x=\"260.7\" y=\"83\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">x</text><text x=\"260.1\" y=\"135.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"441.1\" y=\"128.9\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><polygon points=\"270,120 270,108 282,108 282,120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>",
  secenekler: ["20","15","12","8"],
  dogru: 2,
  hatalar: ["Çevreler arasındaki farkı (60 − 40) cevap yazdın; kenar uzunluğu oranla bulunur.","|BC| = 15 cm değerini yazdın; |DE| kenarı |AB|'nin karşılığıdır, |BC|'nin değil.",null,"|AB| = 8 cm değerini cevap yazdın; DEF büyütülmüş olduğundan |DE|, |AB|'den büyüktür."],
  aciklama: "Dik üçgende dik kenarların kareleri toplamı hipotenüsün karesine eşittir. Benzer üçgenlerde çevreler oranı, benzerlik oranına eşittir.\nAdım 1: |BC|^{2} = 17^{2} − 8^{2} = 289 − 64 = 225 olduğundan |BC| = 15 cm. ABC'nin çevresi 8 + 15 + 17 = 40 cm.\nAdım 2: Oran = 60 / 40 = [[3|2]].\nAdım 3: |DE| ↔ |AB| olduğundan x = 8 · [[3|2]] = 12 cm.\nSağlama: |EF| = 15 · [[3|2]] = 22,5 ve |DF| = 17 · [[3|2]] = 25,5; 12 + 22,5 + 25,5 = 60.\nCevap C."
},
{
  id: "mat-eb-370",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "K, L ve M üç benzer çokgendir. K'nin L'ye benzerlik oranı [[2|3]], M'nin L'ye benzerlik oranı [[4|3]]'tür. M çokgeninin bir kenarı 24 cm'dir.\n**K çokgeninde bu kenarın karşılığı kaç santimetredir?**",
  gorsel: null,
  secenekler: ["48","32","16","12"],
  dogru: 3,
  hatalar: ["K / M oranını ters aldın (2); K, M'den küçüktür, bu yüzden kenarı küçülür.","Yalnızca M / L oranını uyguladın (24 · [[4|3]]); bu, L'nin değil K'nin kenarını vermez.","Yalnızca K / L oranını M'nin kenarına uyguladın (24 · [[2|3]]); K ile M arasındaki oran L üzerinden bulunmalıdır.",null],
  aciklama: "K'nin L'ye oranı [[2|3]] ise K'nin kenarı L'nin karşılık gelen kenarının [[2|3]] katıdır; M için aynı şekilde [[4|3]] katıdır. İki şekli L üzerinden karşılaştırabiliriz.\nAdım 1: L'nin karşılık gelen kenarına t diyelim. Buna göre K'nin kenarı [[2|3]]t, M'nin kenarı [[4|3]]t olur.\nAdım 2: M'nin kenarı 24 olduğundan [[4|3]]t = 24 ve t = 18 cm.\nAdım 3: K'nin kenarı [[2|3]] · 18 = 12 cm.\nSağlama: K / M = 12 / 24 = [[1|2]] = [[2|3]] ÷ [[4|3]].\nCevap D."
},
{
  id: "mat-eb-371",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir kartpostal atölyesi, dikdörtgen biçimli beş kart tasarlamıştır. Kartlardan bazıları yatay, bazıları dikey tutularak ölçüldüğü için genişlik ve yükseklik değerleri tabloda farklı sıralarla yazılmıştır. İki dikdörtgenin benzer olması için karşılık gelen kenarlarının oranlarının eşit olması gerekir.\n**Bu kartlardan kaç farklı çift birbirine benzerdir?**",
  gorsel: "<table class=\"tablo\"><tr><th>Kart</th><th>Genişlik (cm)</th><th>Yükseklik (cm)</th></tr><tr><td>A</td><td>10</td><td>14</td></tr><tr><td>B</td><td>15</td><td>21</td></tr><tr><td>C</td><td>12</td><td>20</td></tr><tr><td>D</td><td>30</td><td>18</td></tr><tr><td>E</td><td>28</td><td>20</td></tr></table>",
  secenekler: ["5","4","3","1"],
  dogru: 1,
  hatalar: ["Benzer olan kartların sayısını saydın (5 kart); soru kart değil, çift sayısını sorar.",null,"Yalnızca 5 : 7 oranlı kartların çiftlerini saydın; 3 : 5 oranlı iki kartın çifti de benzerdir.","Genişlik / yükseklik sırasıyla karşılaştırdın; yatay duran kartları eşleştiremedin. Benzerlikte kısa kenar kısa kenarın, uzun kenar uzun kenarın karşılığıdır."],
  aciklama: "Dikdörtgenlerin bütün açıları 90°'dir; bu yüzden iki dikdörtgenin benzer olması için kısa kenar / uzun kenar oranlarının eşit olması yeter. Kartın yatay ya da dikey durması oranı değiştirmez.\nAdım 1: Her kartta kısa kenarı uzun kenara böl: A 10 / 14 = [[5|7]], B 15 / 21 = [[5|7]], C 12 / 20 = [[3|5]], D 18 / 30 = [[3|5]], E 20 / 28 = [[5|7]].\nAdım 2: Oranı [[5|7]] olan kartlar A, B, E'dir; bunlardan üç çift çıkar: A-B, A-E, B-E.\nAdım 3: Oranı [[3|5]] olan kartlar C ve D'dir; bir çift çıkar: C-D. Toplam 3 + 1 = 4 çift.\nSağlama: Farklı gruplardan iki kart benzer olamaz, çünkü [[5|7]] ile [[3|5]] eşit değildir.\nSık yapılan hata: Genişliği genişlikle, yüksekliği yükseklikle karşılaştırmak; yatay duran kartlar böylece eşleşmez.\nCevap B."
},
{
  id: "mat-eb-372",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "KLM üçgeninde m(K) = 30° ve m(L) = 70°'dir. PRS üçgeninde m(P) = 80° ve m(R) = 30°'dir. Bu iki üçgen birbirine benzerdir ve karşılık gelen köşeler açıların eşitliğine göre eşleşmektedir.\n**Bu benzerlik aşağıdakilerden hangisi gibi yazılır?**",
  gorsel: null,
  secenekler: ["KLM ~ RSP","KLM ~ PSR","KLM ~ PRS","KLM ~ SRP"],
  dogru: 0,
  hatalar: [null,"K ↔ P eşleştirmesi yanlıştır (30° ≠ 80°); m(K) = 30° olan köşe m(R) = 30° olan köşeyle eşleşmelidir.","Köşeleri yazılış sırasına göre eşledin (K ↔ P); oysa m(K) = 30° iken m(P) = 80°'dir. Eşleşme açıların eşitliğine göre yapılmalıdır.","K ↔ S eşleştirmesi yanlıştır; m(S) = 70°, m(K) = 30°. K köşesi R ile eşleşir."],
  aciklama: "Benzer üçgenlerde karşılık gelen açılar eşittir; benzerlik yazılırken eşit açıların köşeleri aynı sırada yazılır.\nAdım 1: Üçüncü açıları bul: m(M) = 180° − 30° − 70° = 80° ve m(S) = 180° − 80° − 30° = 70°.\nAdım 2: Açıları eşle: K (30°) ↔ R (30°), L (70°) ↔ S (70°), M (80°) ↔ P (80°).\nAdım 3: Köşeleri K, L, M sırasıyla yazınca karşılıkları R, S, P olur: KLM ~ RSP.\nSık yapılan hata: Benzerliği harflerin alfabetik sırasına göre yazmak.\nCevap A."
},
{
  id: "mat-eb-373",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Bir oyuncak fabrikası, aynı kalıptan iki dörtgen biçimli parça üretiyor (ABCD ≅ EFGH). ABCD parçasında |AB| = (2x + y) cm ve |BC| = (x − y) cm'dir. EFGH parçasında |EF| = 14 cm ve |FG| = 1 cm'dir (x ve y pozitif sayılardır).\n**x · y çarpımı kaçtır?**",
  gorsel: null,
  secenekler: ["9","10","14","20"],
  dogru: 3,
  hatalar: ["x ve y değerlerini toplayıp sonucu yazdın (5 + 4); sorulan çarpımdır.","Yalnızca 2x değerini yazdın; sorulan x ile y'nin çarpımıdır.","Verilen |EF| = 14 değerini cevap yazdın; x ve y'yi bulup çarpmalısın.",null],
  aciklama: "Eş çokgenlerde karşılık gelen kenarlar eşittir. ABCD ≅ EFGH yazılışında |AB| = |EF| ve |BC| = |FG| olur.\nAdım 1: 2x + y = 14 ve x − y = 1 denklemleri yazılır.\nAdım 2: İki denklemi taraf tarafa topla: 3x = 15 ve x = 5. Buradan y = 5 − 1 = 4.\nAdım 3: x · y = 5 · 4 = 20.\nSağlama: 2 · 5 + 4 = 14 ve 5 − 4 = 1.\nCevap D."
},
{
  id: "mat-eb-374",
  kazanim: "M.8.3.3.1",
  kademe: 3,
  zorluk: 4,
  soru: "Bir ayna atölyesi, yamuk biçimli ABCD aynasını büyüterek EFGH aynasını yapıyor ve ABCD ~ EFGH'dir. ABCD'de AB // DC'dir. Aynaların bazı kenar uzunlukları santimetre cinsinden şekilde verilmiştir; EFGH aynası şekilde ters çevrilmiş olarak çizilmiştir.\n**|GH| = x kaç santimetredir?**",
  gorsel: "<svg viewBox=\"15 6 440 145\" role=\"img\" aria-label=\"Benzer iki yamuk\"><polygon points=\"40,120.9 148,120.9 130,70 58,70\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"28.6\" y=\"134.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">A</text><text x=\"94\" y=\"139.9\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">18 cm</text><text x=\"159.4\" y=\"134.5\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">B</text><text x=\"160.5\" y=\"92.9\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">9 cm</text><text x=\"138.1\" y=\"64.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">C</text><text x=\"94\" y=\"61\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">12 cm</text><text x=\"49.9\" y=\"64.1\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">D</text><polygon points=\"430,30 250,30 280,114.9 400,114.9\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"441.4\" y=\"27.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">E</text><text x=\"238.6\" y=\"27.4\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">F</text><text x=\"240\" y=\"86.3\" font-size=\"14\" text-anchor=\"middle\" fill=\"currentColor\">15 cm</text><text x=\"271.9\" y=\"131.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">G</text><text x=\"340\" y=\"133.9\" font-size=\"14\" text-anchor=\"middle\" fill=\"var(--vurgu)\" font-weight=\"700\">x</text><text x=\"408.1\" y=\"131.8\" font-size=\"16\" text-anchor=\"middle\" fill=\"currentColor\" font-weight=\"700\">H</text></svg>",
  secenekler: ["20","15","12","9"],
  dogru: 0,
  hatalar: [null,"Şekilde verilen |FG| = 15 cm değerini cevap sandın; x, |DC|'nin karşılığı olan |GH|'dir.","|DC| = 12 cm değerini cevap yazdın; EFGH büyütülmüş olduğundan |GH|, |DC|'den büyüktür.","|BC| = 9 cm değerini cevap yazdın; x, |DC|'nin karşılığı olan |GH|'dir."],
  aciklama: "Benzer çokgenlerde karşılık gelen köşeler yazılış sırasına göre eşleşir: ABCD ~ EFGH ise A ↔ E, B ↔ F, C ↔ G, D ↔ H. Şekil ters çizilmiş olsa da eşleşme değişmez.\nAdım 1: |GH| kenarı G ve H köşelerini birleştirir; karşılığı C ve D'yi birleştiren |DC| = 12 cm kenarıdır.\nAdım 2: Oranı bilinen çiftten bul: |FG| ↔ |BC|, 15 / 9 = [[5|3]].\nAdım 3: x = 12 · [[5|3]] = 20 cm.\nSağlama: |EF| = 18 · [[5|3]] = 30 cm ve 20 / 12 = 30 / 18 = [[5|3]].\nCevap A."
},
{
  id: "mat-eb-375",
  kazanim: "M.8.3.3.2",
  kademe: 3,
  zorluk: 4,
  soru: "Bir okulun bahçesinde dörtgen biçimli iki çiçek tarhı vardır: ABCD ve KLMN. Tarhlar benzerdir (ABCD ~ KLMN). ABCD tarhının çevresi 36 m ve en uzun kenarı 12 m'dir. KLMN tarhının en uzun kenarı 20 m'dir.\n**İki tarhın çevreleri arasındaki fark kaç metredir?**",
  gorsel: null,
  secenekler: ["96","60","24","8"],
  dogru: 2,
  hatalar: ["İki çevreyi topladın (36 + 60); soru çevrelerin farkını sorar.","KLMN'nin çevresini buldun (60 m); soru iki çevrenin farkını sorar.",null,"En uzun kenarların farkını (20 − 12) cevap yazdın; çevrelerin farkı için önce KLMN'nin çevresi bulunmalıdır."],
  aciklama: "Benzer çokgenlerde en uzun kenar en uzun kenara karşılık gelir ve çevreler oranı benzerlik oranına eşittir.\nAdım 1: Benzerlik oranı = 20 / 12 = [[5|3]].\nAdım 2: KLMN'nin çevresi 36 · [[5|3]] = 60 m.\nAdım 3: Fark 60 − 36 = 24 m.\nSağlama: 60 / 36 = [[5|3]], oranla tutarlı.\nCevap C."
}
);
